"use client";

import { useMemo, useState } from "react";
import { Icon } from "@/components/nx/Icon";
import type { InstalledMod, ModsOverview } from "@/lib/actions-mod-installs";
import { planToggles } from "@/lib/mods/toggle-policy";
import { goPanelTab, modConfigFolder } from "@/lib/mods/manual-install";

/**
 * "Installed mods" — the server's mod library.
 *
 * Every fact on a row comes from the server or the catalogue: install state
 * and version (ServerMod), health (the last mod-health read of the game log,
 * only for games whose log names each mod), update (the auto-update checker's
 * last result or an on-demand check), dependencies (the server's own mod
 * state file, as of the last mod job). Missing facts are left out, not guessed.
 *
 * Enable/disable is STAGED: flipping switches builds a change list that is
 * checked against the dependency graph and applied as ONE job. Switches only
 * exist where the vetting (lib/mods/toggle-policy.ts) says a disable is
 * possible on this game; content-adding mods need an explicit acknowledgement
 * and are offered a world backup first.
 */

export const SOURCE_LABEL: Record<string, string> = {
  modrinth: "Modrinth", spigotmc: "SpigotMC", hangar: "Hangar", curseforge: "CurseForge", steam_workshop: "Steam Workshop",
  umod: "uMod", github: "GitHub", nexus: "Nexus Mods", thunderstore: "Thunderstore", codefling: "Codefling", mod_io: "mod.io",
  vintagestory_moddb: "Vintage Story ModDB", factorio_portal: "Factorio Mod Portal", ficsit: "ficsit.app", reforger_workshop: "Arma Reforger Workshop",
};

export function fileSize(bytes: number | null): string | null {
  if (!bytes || bytes <= 0) return null;
  return bytes >= 1024 ** 3 ? `${(bytes / 1024 ** 3).toFixed(1)} GB` : bytes >= 1024 * 1024 ? `${Math.round(bytes / 1024 / 1024)} MB` : `${Math.max(1, Math.round(bytes / 1024))} KB`;
}

const STATE: Record<string, { label: string; cls: string }> = {
  INSTALLED: { label: "Enabled", cls: "border-emerald-500/40 bg-emerald-500/10 text-emerald-300" },
  DISABLED: { label: "Disabled", cls: "border-white/20 bg-white/[0.06] text-tx-dim" },
  INSTALLING: { label: "Installing", cls: "border-sky-500/40 bg-sky-500/10 text-sky-300" },
  UPDATING: { label: "Updating", cls: "border-sky-500/40 bg-sky-500/10 text-sky-300" },
  ENABLING: { label: "Enabling", cls: "border-sky-500/40 bg-sky-500/10 text-sky-300" },
  DISABLING: { label: "Disabling", cls: "border-amber-500/40 bg-amber-500/10 text-amber-300" },
  REMOVING: { label: "Removing", cls: "border-amber-500/40 bg-amber-500/10 text-amber-300" },
  FAILED: { label: "Failed", cls: "border-red-500/40 bg-red-500/10 text-red-300" },
};
export const PENDING = new Set(["INSTALLING", "UPDATING", "ENABLING", "DISABLING", "REMOVING"]);

const HEALTH: Record<string, { label: string; cls: string; icon: string; tip: string }> = {
  loaded: { label: "Loaded", cls: "border-emerald-500/35 bg-emerald-500/[0.08] text-emerald-300", icon: "checkcircle", tip: "Seen loading in the game log after the last start" },
  error: { label: "Load error", cls: "border-red-500/40 bg-red-500/10 text-red-300", icon: "warntriangle", tip: "The game log shows an error naming this mod" },
  "not-seen": { label: "Not seen in log", cls: "border-amber-500/40 bg-amber-500/[0.08] text-amber-300", icon: "warncircle", tip: "The mod framework started but this mod's load line wasn't in the log" },
};

export function Chip({ cls, icon, children, title }: { cls: string; icon?: string; children: React.ReactNode; title?: string }) {
  return (
    <span title={title} className={"inline-flex items-center gap-1 rounded-[6px] border px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide " + cls}>
      {icon && <Icon name={icon} size={10} tone="inherit" />}
      {children}
    </span>
  );
}

export function ModIcon({ m, size = 40 }: { m: { iconUrl: string | null }; size?: number }) {
  return (
    <span className="grid flex-none place-items-center overflow-hidden rounded-[11px] border border-rim-hi bg-well" style={{ width: size, height: size }}>
