}

export const btnGhost = "rounded-[10px] border border-rim-hi bg-well px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:border-brand-400/45 hover:text-white disabled:opacity-50";

function Switch({ on, disabled, onChange, label }: { on: boolean; disabled?: boolean; onChange: (v: boolean) => void; label: string }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={on}
      aria-label={label}
      title={label}
      disabled={disabled}
      onClick={() => onChange(!on)}
      className="group relative h-[22px] w-[40px] flex-none rounded-full transition focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-brand-400 disabled:cursor-not-allowed disabled:opacity-45"
    >
