export const dynamic = "force-dynamic";

export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  const body = (await req.json().catch(() => ({}))) as { serverId?: string; restart?: boolean };
  const serverId = String(body.serverId || "");
  if (!serverId) return NextResponse.json({ error: "Pick a server." }, { status: 400 });
  const rl = checkRateLimit(`mb:install:${o.user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return NextResponse.json({ error: `Too many requests. Retry in ${rl.retryAfterSec}s.` }, { status: 429 });

  const r = await installBuildToServer(o.build, o.user.id, serverId);
  if (!r.ok) return NextResponse.json({ error: r.error }, { status: 400 });

  let restarted = false;
  let restartNote: string | null = null;
  if (body.restart) {
    const p = await gamePower(serverId, "restart");
    restarted = p.ok;
    if (!p.ok) restartNote = p.error;
  }
  const lastInstall = { serverId, serverName: r.serverName, at: new Date().toISOString(), replaced: r.replaced, backupDir: r.backupDir, restarted };
  await db.modBuild.update({ where: { id: o.build.id }, data: { lastInstall } });
  await db.auditLog.create({ data: { userId: o.user.id, action: "modbuilder.install", detail: `${o.build.id} -> ${serverId} ${r.path}${r.replaced.length ? ` (replaced ${r.replaced.join(", ")}, backup ${r.backupDir})` : ""}` } }).catch(() => {});
  return NextResponse.json({ ok: true, path: r.path, replaced: r.replaced, backupDir: r.backupDir, restarted, restartNote });
}
import { NextResponse } from "next/server";
