/**
 * GAME_MOD_SYNC handler — reconcile a game server's installed mods to the desired
 * state recorded in `ServerMod` rows:
 *   - status INSTALLING → fetch + install the mod, then INSTALLED (or FAILED)
 *   - status REMOVING   → remove the mod, then delete the row (or FAILED)
 *
 * Wire into worker/index.ts handlers:  GAME_MOD_SYNC: gameModSync,
 *
 * ENGINE FAMILIES (2026-10-01 — minecraft, valheim, rust, cs2, factorio; see
 * lib/mods/installers/index.ts) go through lib/mods/engine.ts: verified
 * download, dependency resolution, safe placement, guest state file, rollback,
 * plus UPDATING / DISABLING / ENABLING. In SANDBOX they run the SAME pipeline
 * against a fake guest directory (lib/mods/guest-fs.ts LocalGuestFs) — real
 * downloads, real files, no simulated success.
 *
 * Every other family keeps the THREE PATHS below, mirroring game-config's
 * honesty guard so we never tell a customer a mod is installed when nothing
 * was written to their server:
 *  - SANDBOX: simulate (flip INSTALLING→INSTALLED, REMOVING→REMOVED). Dev only.
 *  - REAL (ENABLE_REAL_GAMEMODS=1, not sandbox): install/remove over SSH via the
 *    per-source adapter. Where an adapter isn't implemented yet, the mod is marked
 *    FAILED with a clear reason — never silently "INSTALLED".
 *  - Neither (production, flag off): mark the queued changes FAILED with a plain
 *    message. A change we did NOT apply is a failure and must say so.
 */

const REAL_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMEMODS === "1";

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[game-mods] notify failed", e);
  }
}

export async function gameModSync(job: Job): Promise<void> {
  const serverId = job.serverId;
  if (!serverId) throw new Error("game mod sync: job has no serverId");

  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
  });
  if (!server) throw new Error(`Server ${serverId} not found`);

  const pending = orderPendingByPlan(
    await db.serverMod.findMany({
      where: { serverId, status: { in: [...ENGINE_PENDING_STATUSES] } },
      include: { mod: true },
      orderBy: { updatedAt: "asc" },
    }),
    job.payload,
  );
  if (pending.length === 0) return;

  const installedNames: string[] = [];
  const removedNames: string[] = [];
  const failedNames: string[] = [];
  const changed: string[] = [];
  let restartRequired = false;
  let depGraph: Record<string, string[]> | null = null;

  // ── engine families (lib/mods/installers/*) — one guest connection per job ──
  let guest: GuestFs | null = null;
  let sshGuest: SshGuestFs | null = null;
  const engineRows = pending.filter((sm) => engineInstallerFor(sm.mod.gameFamily, sm.mod.source));
  const legacyRows = pending.filter((sm) => !engineInstallerFor(sm.mod.gameFamily, sm.mod.source));
  const step = async (text: string, pct: number) => {
    await db.job.update({ where: { id: job.id }, data: { step: text.slice(0, 180), progress: Math.max(0, Math.min(99, pct)) } }).catch(() => {});
  };

  try {
    for (const [n, sm] of engineRows.entries()) {
      const installer = engineInstallerFor(sm.mod.gameFamily, sm.mod.source)!;
      const op = sm.status;
      let result: OpResult;
      // Defense in depth: the portal only queues toggles the vetting allows
      // (lib/mods/toggle-policy.ts); a row that got here any other way is refused.
      const toggleBlocked =
        op === "DISABLING" || op === "ENABLING"
          ? (() => {
              const d = toggleDecision({ family: sm.mod.gameFamily, variant: server.gameVariant ?? null, mod: sm.mod, engine: true });
              return d.allowed ? null : d.reason;
            })()
          : null;
      if (toggleBlocked) {
        result = { ok: false, error: toggleBlocked };
      } else if (!SANDBOX && !REAL_ENABLED) {
        result = { ok: false, error: "Mod installation is being enabled for this game — your change was not applied yet. Our team has been notified." };
      } else {
        try {
          if (!guest) {
            if (SANDBOX) {
              const local = new LocalGuestFs(sandboxGuestRoot(server.id));
              await seedSandboxGuest(local, sm.mod.gameFamily, server.gameVariant ?? null);
              guest = local;
            } else {
              sshGuest = await SshGuestFs.open(server);
              guest = sshGuest;
            }
          }
          const deps: EngineDeps = {
            fs: guest,
            fetcher: safeFetch,
            mirror: dbMirrorLookup((sql, ...args) => db.$queryRawUnsafe(sql, ...args)),
            progress: (text, pct) => step(`${sm.mod.name}: ${text}`, Math.round(((n + pct / 100) / engineRows.length) * 100)),
          };
          const facts = serverFacts(server, sm.mod.gameFamily);
          const cf = catalogFacts(sm.mod);
          result =
            op === "REMOVING" ? await engineUninstall(installer, cf, facts, deps)
            : op === "DISABLING" ? await engineSetDisabled(installer, cf, facts, deps, true)
            : op === "ENABLING" ? await engineSetDisabled(installer, cf, facts, deps, false)
            : await installOrUpdate(installer, cf, facts, deps, op === "UPDATING" ? "update" : "install");
        } catch (e) {
          result = { ok: false, error: e instanceof Error ? e.message : String(e) };
        }
      }

      const label = `${op.toLowerCase()} ${sm.mod.slug}`;
      if (result.ok) {
        restartRequired ||= result.restartRequired;
        changed.push(...result.changed);
        if (op === "REMOVING") {
          await db.serverMod.delete({ where: { id: sm.id } });
          removedNames.push(sm.mod.name);
        } else {
