}

/**
 * Apply several enable/disable/remove changes in one job (the Installed
 * list's batch bar). Checked here exactly like single changes — ownership,
 * the vetting's toggle policy, the content-risk acknowledgement, and the
 * dependency plan — then queued all-or-nothing in the order planToggles()
 * says is safe.
 */
export async function panelApplyModBatch(
  serverId: string,
  changes: { modId: string; op: "disable" | "enable" | "remove" }[],
  opts?: { ackRisk?: boolean },
): Promise<{ ok?: true; error?: string; jobId?: string }> {
  const { user, server, family } = await ownedServer(serverId);
  if (!family) return { error: "This server doesn't support mods." };
  if (server.status !== "RUNNING") return { error: "Start the server's VM first — mods are changed on the running server." };
  if (!installsLive()) return { error: PAUSED_ERROR };
  if (!Array.isArray(changes) || changes.length === 0) return { error: "Nothing to apply." };
  if (changes.length > MAX_BATCH) return { error: `Apply at most ${MAX_BATCH} changes at once.` };
  const clean = changes
    .filter((c) => c && typeof c.modId === "string" && c.modId.length <= 64 && ["disable", "enable", "remove"].includes(c.op))
    .map((c) => ({ modId: c.modId, op: c.op }));
  if (clean.length !== changes.length) return { error: "That change list isn't valid." };
  const rows = await db.serverMod.findMany({ where: { serverId }, include: { mod: true } });
  const byId = new Map(rows.map((r) => [r.modId, r]));
  for (const c of clean) {
    const r = byId.get(c.modId);
    if (!r || r.mod.gameFamily !== family) return { error: "One of those mods isn't installed on this server." };
    if (c.op !== "remove") {
      if (!engineInstallerFor(family, r.mod.source)) return { error: `${r.mod.name} can't be switched on or off on this game.` };
      const d = toggleDecision({ family, variant: server.gameVariant ?? null, mod: r.mod, engine: true });
      if (!d.allowed) return { error: `${r.mod.name}: ${d.reason}` };
      if (c.op === "disable" && d.needsAck && !opts?.ackRisk) return { error: RISK_ACK_ERROR };
    }
  }
  // Dependencies, against the last graph the worker published.
  const graph = (await lastDepGraph(serverId))?.graph ?? {};
  const enabled = new Set(rows.filter((r) => r.status === "INSTALLED").map((r) => r.modId));
  const names = Object.fromEntries(rows.map((r) => [r.modId, r.mod.name]));
  const toggles = clean.filter((c): c is { modId: string; op: "disable" | "enable" } => c.op !== "remove");
  // A removal takes the mod out of the enabled set too (the engine also refuses removing something others need).
  const plan = planToggles([...toggles, ...clean.filter((c) => c.op === "remove").map((c) => ({ modId: c.modId, op: "disable" as const }))], graph, enabled, names);
  if (!plan.ok) return { error: plan.problems[0] };
  const removes = clean.filter((c) => c.op === "remove");
  const ordered: BatchOp[] = [
    ...plan.order.filter((p) => !removes.some((r) => r.modId === p.modId)).map((p) => ({ modId: p.modId, op: p.op as ModOp })),
    ...removes.map((r) => ({ modId: r.modId, op: "remove" as ModOp })),
  ];
  // Disables before removals before enables keeps every intermediate state valid.
  const finalOrder = [...ordered.filter((o) => o.op === "disable"), ...ordered.filter((o) => o.op === "remove"), ...ordered.filter((o) => o.op === "enable")];
  const slugs = new Map(rows.map((r) => [r.modId, r.mod.slug]));
  const r = await enqueueModBatch(serverId, finalOrder, { userId: user.id, slugs, detail: opts?.ackRisk ? "risk-acknowledged" : undefined });
  if (!r.ok) return { error: r.error };
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true, jobId: r.jobId };
}
export async function panelEnableMod(serverId: string, modId: string) {
  return act(serverId, modId, "enable");
}

/** Latest upstream version for each installed engine mod (on demand, capped). */
export async function checkModUpdates(serverId: string): Promise<{ error?: string; updates?: Record<string, string | null> }> {
  const { user, server, family } = await ownedServer(serverId);
  if (!family) return { error: "This server doesn't support mods." };
  if (throttled(user.id, "mod-updates", 4)) return { error: "Checked very recently — try again in a minute." };
  const rows = await db.serverMod.findMany({ where: { serverId, status: { in: ["INSTALLED", "DISABLED"] } }, include: { mod: true }, take: 15 });
  const facts = serverFacts(server, family);
  const work = rows.filter((r) => engineInstallerFor(family, r.mod.source));
  const out: Record<string, string | null> = {};
  let i = 0;
  await Promise.all(
    Array.from({ length: 3 }, async () => {
      while (i < work.length) {
        const r = work[i++];
        const inst = engineInstallerFor(family, r.mod.source)!;
        const p = await previewResolve(inst, catalogFacts(r.mod), facts, safeFetch, PREVIEW_LAYOUT(facts.pinnedVersion)).catch(() => null);
        const root = p && p.ok ? p.packages.find((x) => x.root) : null;
        out[r.modId] = root ? root.version : null;
      }
    }),
  );
  return { updates: out };
}

