    v: 1,
    name: displayName(chain),
    pluginName: cur.pluginName,
    tagline: clip(s?.tagline, 200) || null,
    summary: clip(s?.text, 4000) || null,
    howToUse: strArr(s?.howToUse, 20, 400),
    limitations: strArr(s?.limitations, 20, 400),
    commands: (r?.commands ?? []).slice(0, 60),
    permissions: (r?.permissions ?? []).slice(0, 80),
    config: (r?.config ?? []).slice(0, 80),
    compat: {
      software: [...CYRUS_SOFTWARE],
      mcVersions: mc,
      note: `Built against the Paper API for Minecraft ${cur.mcVersion}. Runs on Paper and Purpur; not on Spigot, Folia, Fabric or Forge.`,
    },
    versions,
    currentBuildId: cur.id,
    files: (r?.files ?? []).filter((f) => /^src\//.test(f.path)).slice(0, 200),
    generatedAt: now.toISOString(),
  };
