"use server";

/**
 * Mods tab → Cyrus mods on one server: version history with notes, switch to
 * the latest or any earlier version (rollback), and start tracking a jar an
 * older builder install left on the server.
 *
 * Every switch is the normal engine path: ServerMod → UPDATING with
 * targetVersionId = the chosen build, one GAME_MOD_SYNC job under the per-server
 * lock (lib/mods/queue.ts). The engine backs up the jar it replaces.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { familyFor } from "./game-config";
import { SANDBOX } from "./sandbox";
import { enqueueModOp } from "./mods/queue";
import { CYRUS_SOURCE } from "./mods/installers/cyrus";
import { cyrusVersionHistory, type CyrusVersionRow } from "./cyrus-mods/installed";
import { installBuildToServer } from "./modbuilder/install";
import { cyrusAccessFor } from "./cyrus-mods/gate";

async function ownedCyrusRow(serverId: string, modId: string) {
  const user = await requireUser();
  if (typeof serverId !== "string" || serverId.length > 64 || typeof modId !== "string" || modId.length > 64) throw new Error("Not found");
  const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true } });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) throw new Error("Not found");
  const row = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId } }, include: { mod: true } });
  if (!row || row.mod.source !== CYRUS_SOURCE || !row.mod.sourceId) throw new Error("Not found");
  return { user, server, row, rootBuildId: row.mod.sourceId };
}

export async function getCyrusVersions(serverId: string, modId: string): Promise<{ error?: string; name?: string; status?: string; versions?: CyrusVersionRow[]; pageHref?: string | null; canSwitch?: boolean; why?: string | null }> {
  try {
    const { user, server, row, rootBuildId } = await ownedCyrusRow(serverId, modId);
    const versions = await cyrusVersionHistory(rootBuildId, row.versionId);
    const page = await db.cyrusModPage.findUnique({ where: { rootBuildId }, select: { slug: true } });
    const access = await cyrusAccessFor(user);
    const why = row.status !== "INSTALLED" ? (row.status === "DISABLED" ? "Switch it on first to change its version." : "Wait for the current change to finish.")
      : server.status !== "RUNNING" ? "Start the server to change versions."
      : null;
    return { name: row.mod.name, status: row.status, versions, pageHref: page && access.allowed ? `/dashboard/nxlabs/cyrus/${page.slug}` : null, canSwitch: !why, why };
  } catch {
    return { error: "Couldn't load this mod's versions." };
  }
}

export async function switchCyrusVersion(serverId: string, modId: string, buildId: string): Promise<{ ok?: true; error?: string; jobId?: string }> {
  let ctx;
  try {
    ctx = await ownedCyrusRow(serverId, modId);
  } catch {
    return { error: "Not found." };
  }
  const { user, server, row, rootBuildId } = ctx;
  if (familyFor(server) !== "minecraft") return { error: "Not found." };
  if (server.status !== "RUNNING") return { error: "Start the server's VM first — mods are changed on the running server." };
  if (!SANDBOX && process.env.ENABLE_REAL_GAMEMODS !== "1") return { error: "One-click mod changes are paused right now, so nothing was queued." };
  if (row.status !== "INSTALLED") return { error: row.status === "DISABLED" ? `${row.mod.name} is switched off — switch it on first.` : `${row.mod.name} is busy right now.` };
  if (typeof buildId !== "string" || !/^[A-Za-z0-9_-]{1,64}$/.test(buildId)) return { error: "Pick a version." };
  if (row.versionId === buildId) return { error: "That version is already on the server." };
  const b = await db.modBuild.findUnique({ where: { id: buildId } });
  if (!b || (b.rootBuildId ?? b.id) !== rootBuildId || b.status !== "succeeded" || !b.jarPath) return { error: "That isn't a finished version of this mod." };
  if (b.userId !== server.userId) return { error: "Not found." };
  const r = await enqueueModOp(serverId, modId, "update", { userId: user.id, slug: row.mod.slug }, { targetVersionId: buildId });
  if (!r.ok) return { error: r.error };
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true, jobId: r.jobId };
}

/** Bring a pre-engine builder install under the Mods tab (re-installs the same build through the engine). */
export async function trackCyrusInstall(serverId: string, buildId: string): Promise<{ ok?: true; error?: string }> {
  const user = await requireUser();
  if (typeof buildId !== "string" || buildId.length > 64 || typeof serverId !== "string" || serverId.length > 64) return { error: "Not found." };
  const b = await db.modBuild.findUnique({ where: { id: buildId } });
  if (!b || b.userId !== user.id) return { error: "Not found." };
  const r = await installBuildToServer(b, user.id, serverId, { waitMs: 0 });
  if (!r.ok) return { error: r.error };
  await db.auditLog.create({ data: { userId: user.id, action: "modbuilder.track", detail: `${b.id} -> ${serverId}` } }).catch(() => {});
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}

