/**
 * "Built with Cyrus" mark for mods made with Nxeon's AI mod studio.
 *
 * SWAPPABLE: every Cyrus-mod surface (Mods tab rows, NxLabs cards and pages,
 * the version dialog) renders the mark ONLY through this component, so the
 * Cyrus redesign (branch feature/cyrus-modbuilder) can replace the artwork in
 * this one file. Keep the props stable: `size` and `tone`.
 *
 * Design: a small typographic seal — a ringed monogram plus the word set in
 * small caps. No sparkles, no glow. Uses theme tokens only, so it reads on
 * dark and light surfaces; `tone="onDark"` pins it for dark islands.
 */
export type CyrusBadgeProps = {
  size?: "xs" | "sm" | "md";
  /** "auto" follows the theme; "onDark" for dark-island surfaces (heroes, dark modals). */
  tone?: "auto" | "onDark";
  /** Hide the word and show only the seal (tight rows). The label stays for screen readers. */
  sealOnly?: boolean;
  className?: string;
  title?: string;
};

const DIM = { xs: { seal: 13, text: 9.5, pad: "px-1.5 py-[1px]", gap: "gap-1" }, sm: { seal: 15, text: 10.5, pad: "px-1.5 py-0.5", gap: "gap-1.5" }, md: { seal: 19, text: 12, pad: "px-2 py-1", gap: "gap-1.5" } };

export function CyrusSeal({ size = 15, className = "" }: { size?: number; className?: string }) {
  return (
    <svg width={size} height={size} viewBox="0 0 20 20" aria-hidden className={className} focusable="false">
      <circle cx="10" cy="10" r="8.6" fill="none" stroke="currentColor" strokeWidth="1.3" />
      <circle cx="10" cy="10" r="6.4" fill="none" stroke="currentColor" strokeWidth="0.7" strokeDasharray="1.2 1.4" opacity="0.7" />
      {/* monogram C: an open arc */}
      <path d="M12.9 7.3a3.9 3.9 0 1 0 0 5.4" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" />
    </svg>
  );
}

export function CyrusBadge({ size = "sm", tone = "auto", sealOnly = false, className = "", title = "Built with Cyrus, Nxeon's AI mod studio" }: CyrusBadgeProps) {
  const d = DIM[size];
  const ink = tone === "onDark" ? "border-[#b9a6ff]/45 bg-[#8c3ae9]/15 text-[#d9ceff]" : "border-violet/40 bg-violet/10 text-violet";
  return (
    <span
      title={title}
      className={`inline-flex flex-none items-center ${d.gap} rounded-full border ${ink} ${sealOnly ? "p-[2px]" : d.pad} font-bold uppercase leading-none tracking-[0.12em] ${className}`}
      style={{ fontSize: d.text }}
      data-cyrus-badge
    >
      <CyrusSeal size={d.seal} />
      {sealOnly ? <span className="sr-only">Cyrus</span> : <span>Cyrus</span>}
    </span>
  );
}

