"use client";

import { useCallback, useEffect, useRef, useState, useTransition, useMemo } from "react";
import { Icon } from "@/components/nx/Icon";
import {
  checkModUpdates,
  getModsOverview,
  panelApplyModBatch,
  panelInstallMod,
  panelRemoveMod,
  panelUpdateMod,
  previewModInstall,
  type InstallPreview,
  type InstalledMod,
  type ModsOverview,
} from "@/lib/actions-mod-installs";
import { createGameBackup, gamePower } from "@/lib/actions-game-control";
import type { Compat } from "@/lib/mods/types";
import type { BrowseCard } from "@/lib/mods-browse";
import { ModBrowser } from "@/components/customer/mods/browser/ModBrowser";
import { AutoUpdatePanel } from "@/components/customer/mods/AutoUpdatePanel";
import { Chip, InstalledLibrary, ModIcon, PENDING, SOURCE_LABEL, fileSize, hasUpdateFor, type StagedOp } from "./mods/InstalledLibrary";
import { HealthView, healthIssues } from "./mods/HealthView";
import { CyrusVersionsDialog, CyrusUpdates } from "./mods/CyrusVersions";

/**
 * Mods & Plugins — ONE primary view and three secondary ones (2026-10-07
 * declutter; every capability of the earlier stacked layout is kept):
 *
 *  INSTALLED (default when anything is installed): the server's library —
 *    version, source, health, updates, dependencies, uninstall, staged on/off
 *    switches where the vetting (lib/mods/toggle-policy.ts) allows them, and
 *    Cyrus mods (badge + version history / update / rollback).
 *  BROWSE: the whole catalogue for this game with compatibility for THIS
 *    server and a live dependency preview before install. (The old Mods /
 *    Plugins sub-tabs became the store's category filter.)
 *  UPDATES: one-off updates, automatic updates, schedule, player profiles,
 *    history (components/customer/mods/AutoUpdatePanel.tsx).
 *  HEALTH: load on this tier, per-mod load verdicts from the game log,
 *    failed installs, dependencies, manual installs + backups.
 *
 * Above the views there is at most one compact notice per live condition
 * (job progress, restart needed, one-click paused, heavy load) instead of
 * stacked banner cards. Deep links: ?tab=mods#mod-updates / #mod-health /
 * #mod-store, ?tab=plugins opens Browse on plugins.
 *
 * Honesty rules (unchanged): every number is the source's own or absent; a
 * change the worker could not apply comes back as a failure with its reason;
 * when one-click changes are switched off the tab says so and offers no
 * button that would only fail.
 */

const PLUGIN_CATS = ["admin", "permission", "protection", "economy", "chat", "discord", "core", "utility", "clan", "rank", "teleport", "plugins"];

/** What the install dialog needs — satisfied by a browser card. */
type InstallTarget = { id: string; name: string; source: string; iconUrl: string | null; compat: Compat | null; impact: string; impactNote: string | null; url: string | null };
const fromCard = (m: BrowseCard): InstallTarget => ({ id: m.id, name: m.name, source: m.source, iconUrl: m.icon, compat: m.compat, impact: m.impact, impactNote: null, url: null });

export type ModsView = "installed" | "browse" | "updates" | "health";
const HASH: Record<string, ModsView> = { "#mod-updates": "updates", "#mod-health": "health", "#mod-store": "browse", "#mod-installed": "installed" };
const HASH_OF: Record<ModsView, string> = { installed: "#mod-installed", browse: "#mod-store", updates: "#mod-updates", health: "#mod-health" };

function Notice({ tone, icon, title, body, action, live }: { tone: "info" | "warn" | "bad" | "ok"; icon: string; title: React.ReactNode; body?: React.ReactNode; action?: React.ReactNode; live?: boolean }) {
  const t = {
    info: "border-cyan/35 bg-cyan/[0.07] text-cyan",
    warn: "border-amber/45 bg-amber/[0.08] text-amber",
    bad: "border-rose/40 bg-rose/[0.08] text-rose",
    ok: "border-mint/35 bg-mint/[0.08] text-mint",
  }[tone];
  return (
    <div className={"flex flex-wrap items-center gap-x-3 gap-y-2 rounded-[13px] border px-3.5 py-2.5 " + t} role={tone === "bad" ? "alert" : "status"} aria-live={live ? "polite" : undefined}>
      <Icon name={icon} size={14} tone="inherit" className={"flex-none " + (icon === "refresh" ? "animate-spin" : "")} />
      <div className="min-w-0 flex-1">
        <p className="text-[12.5px] font-bold">{title}</p>
        {body && <div className="mt-0.5 text-[12px] leading-relaxed text-tx-dim">{body}</div>}
      </div>
      {action}
    </div>
  );
}

export function ModsPanel({ serverId, scope }: { serverId: string; scope: "mods" | "plugins" }) {
  const [ov, setOv] = useState<ModsOverview | null>(null);
  const [fatal, setFatal] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [view, setViewState] = useState<ModsView | null>(null);
  const [total, setTotal] = useState<number | null>(null);
  const [refreshKey, setRefreshKey] = useState(0);
  const [confirm, setConfirm] = useState<InstallTarget | null>(null);
  const [removing, setRemoving] = useState<InstalledMod | null>(null);
  const [versionsOf, setVersionsOf] = useState<InstalledMod | null>(null);
  const [riskBatch, setRiskBatch] = useState<{ changes: { modId: string; op: StagedOp }[]; risky: InstalledMod[] } | null>(null);
  const [updates, setUpdates] = useState<Record<string, string | null> | null>(null);
  const [checking, setChecking] = useState(false);
  const [restarting, setRestarting] = useState(false);
  const [, start] = useTransition();

  const setView = useCallback((v: ModsView) => {
    setViewState(v);
    try {
      const url = new URL(window.location.href);
      url.hash = HASH_OF[v];
      window.history.replaceState(window.history.state, "", url);
    } catch { /* non-browser */ }
  }, []);

  const loadOverview = useCallback(async () => {
    const r = await getModsOverview(serverId).catch(() => ({ error: "Couldn't load your mods." }) as { error: string });
    if ("view" in r && r.view) {
      setOv(r.view);
      setFatal(null);
    } else if ("error" in r && r.error) setFatal(r.error);
  }, [serverId]);

  useEffect(() => { void loadOverview(); }, [loadOverview]);

  // First view: a deep link (#mod-updates…) or ?tab=plugins wins; else the
  // library when there is one, the store when there isn't.
  useEffect(() => {
    if (!ov || view !== null) return;
    const fromHash = typeof window !== "undefined" ? HASH[window.location.hash] : undefined;
    setViewState(fromHash ?? (scope === "plugins" ? "browse" : ov.installed.some((m) => m.status !== "REMOVED") ? "installed" : "browse"));
  }, [ov, view, scope]);

  // Plugins deep link = the catalogue's admin-ish categories (a filter, said plainly).
  const pluginCategory = useMemo(() => {
    if (scope !== "plugins" || !ov) return null;
    return ov.categories.find((c) => PLUGIN_CATS.some((k) => c.category.toLowerCase().includes(k)))?.category ?? null;
  }, [scope, ov]);

  // Follow the job while one is queued/running, then refresh the store's results once.
  const active = !!ov?.job || (ov?.installed ?? []).some((m) => m.status && PENDING.has(m.status));
  const wasActive = useRef(false);
  useEffect(() => {
    if (!active) {
      if (wasActive.current) {
        wasActive.current = false;
        setRefreshKey((k) => k + 1);
      }
      return;
    }
    wasActive.current = true;
    const t = setInterval(() => void loadOverview(), 3000);
    return () => clearInterval(t);
  }, [active, loadOverview]);

  const run = (fn: () => Promise<{ error?: string } | null | undefined>, ok?: string) =>
    start(async () => {
      setError(null);
      setNotice(null);
      const r = await fn().catch(() => ({ error: "Couldn't reach the server." }));
      if (r && r.error) setError(r.error);
      else if (ok) setNotice(ok);
      await loadOverview();
      setRefreshKey((k) => k + 1);
    });

  const install = (m: InstallTarget, ackClient: boolean) => {
    setConfirm(null);
    run(() => panelInstallMod(serverId, m.id, { ackClient }), `Installing ${m.name} — it will appear under Installed.`);
  };
  const applyBatch = (changes: { modId: string; op: StagedOp }[], ackRisk: boolean) => {
    setRiskBatch(null);
    run(() => panelApplyModBatch(serverId, changes, { ackRisk }));
  };

  const restartNow = () =>
    start(async () => {
      setRestarting(true);
      setError(null);
      const r = await gamePower(serverId, "restart").catch(() => ({ ok: false as const, error: "Couldn't reach the server." }));
      if (!r.ok) setError(r.error);
      await loadOverview();
      setRestarting(false);
    });

  const doCheckUpdates = () =>
    start(async () => {
      setChecking(true);
      const r = await checkModUpdates(serverId).catch(() => ({ error: "Couldn't check for updates." }) as { error: string });
      if ("updates" in r && r.updates) setUpdates(r.updates);
      else if ("error" in r && r.error) setError(r.error);
      setChecking(false);
    });

  if (!ov && !fatal) {
    return <div className="rounded-[16px] border border-rim-hi bg-surface px-6 py-16 text-center text-[13px] text-tx-dim">Loading mods…</div>;
  }
  if (!ov) {
    return (
      <div className="rounded-[16px] border border-rim-hi bg-surface px-6 py-14 text-center">
        <Icon name="cube" size={28} className="mx-auto" />
        <p className="mt-3 text-[14.5px] font-bold text-tx">Mods aren&apos;t available for this game</p>
        <p className="mx-auto mt-1.5 max-w-[52ch] text-[12.5px] leading-relaxed text-tx-dim">{fatal}</p>
      </div>
    );
  }

  const unavailable = ov.coverage.mode === "unavailable";
  const installedVisible = ov.installed.filter((m) => m.status !== "REMOVED");
  const enabledCount = installedVisible.filter((m) => m.status === "INSTALLED").length;
  const disabledCount = installedVisible.filter((m) => m.status === "DISABLED").length;
  const updateCount = installedVisible.filter((m) => m.status === "INSTALLED" && hasUpdateFor(m, updates)).length;
  const issues = healthIssues(ov);
  const cur: ModsView = view ?? "installed";
  const cyrusUpdates = installedVisible.filter((m) => m.cyrus?.updateAvailable && m.status === "INSTALLED");

  const tabs: { k: ModsView; icon: string; label: string; count: string | null; dot?: "warn" | "info" }[] = [
    { k: "installed", icon: "layers", label: "Installed", count: String(installedVisible.length) },
    { k: "browse", icon: "cart", label: "Browse", count: unavailable ? null : (total ?? ov.catalogTotal) >= 1000 ? `${Math.round((total ?? ov.catalogTotal) / 100) / 10}k` : String(total ?? ov.catalogTotal) },
    { k: "updates", icon: "refresh2", label: "Updates", count: updateCount ? String(updateCount) : null, dot: updateCount ? "info" : undefined },
    { k: "health", icon: "activity", label: "Health", count: issues.count ? String(issues.count) : null, dot: issues.count ? "warn" : undefined },
  ];

  return (
    <div className="flex flex-col gap-3" data-testid="mods-panel">
      {/* ── compact header: what this is, what it's checked against, the counts ── */}
      <header className="flex flex-wrap items-center gap-x-5 gap-y-3 rounded-[16px] border border-rim-hi bg-surface px-4 py-3.5 sm:px-5">
        <span className="grid h-[40px] w-[40px] flex-none place-items-center rounded-[12px] bg-[linear-gradient(140deg,#2f7eef,#8c3ae9)] text-[#fff]">
          <Icon name="cube" size={17} tone="inherit" />
        </span>
        <div className="min-w-0 flex-1">
          <h2 className="text-[16.5px] font-extrabold tracking-[-0.015em] text-tx">Mods &amp; Plugins</h2>
          <p className="mt-0.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-[12px] text-tx-dim">
            <span className="rounded-[6px] border border-rim-hi bg-well px-1.5 py-0.5 font-semibold text-tx">{ov.variant ?? "server"}{ov.gameVersion ? ` · ${ov.gameVersion}` : ""}</span>
            {unavailable ? <span>Manual install only</span> : !ov.installsLive ? <span className="inline-flex items-center gap-1 font-semibold text-amber"><Icon name="lock" size={10} tone="inherit" />One-click paused</span> : <span className="inline-flex items-center gap-1 font-semibold text-cyan"><Icon name="bolt" size={10} tone="inherit" />One-click</span>}
            <span className="hidden text-tx-faint sm:inline">· compatibility is checked against this server</span>
          </p>
        </div>
        <dl className="flex flex-none gap-5" aria-label="Mod counts">
          <div className="flex flex-col items-end">
            <dt className="text-[10px] font-bold uppercase tracking-[0.13em] text-tx-faint">On</dt>
            <dd className="num text-[18px] font-extrabold leading-tight text-tx">{enabledCount}</dd>
          </div>
          <div className="flex flex-col items-end">
            <dt className="text-[10px] font-bold uppercase tracking-[0.13em] text-tx-faint">Off</dt>
            <dd className="num text-[18px] font-extrabold leading-tight text-tx-dim">{disabledCount}</dd>
          </div>
          <div className="flex flex-col items-end">
            <dt className="text-[10px] font-bold uppercase tracking-[0.13em] text-tx-faint">Updates</dt>
            <dd className={"num text-[18px] font-extrabold leading-tight " + (updateCount ? "text-cyan" : "text-tx-dim")}>{updateCount}</dd>
          </div>
        </dl>
      </header>

      {/* ── live conditions: one compact line each, most urgent first ── */}
      {ov.job && (
        <div className="rounded-[13px] border border-cyan/35 bg-cyan/[0.07] px-3.5 py-2.5" role="status" aria-live="polite">
          <div className="flex items-center gap-2.5 text-cyan">
            <Icon name="refresh" size={13} tone="inherit" className="animate-spin" />
            <p className="min-w-0 flex-1 truncate text-[12.5px] font-semibold">
              {ov.job.status === "QUEUED" ? "Queued — waiting for the server to be free" : ov.backupRunning ? "Backing up your world…" : ov.job.step ?? "Working…"}
            </p>
            <span className="num text-[12px] font-bold">{ov.job.progress}%</span>
          </div>
          <div className="mt-2 h-[4px] overflow-hidden rounded-full bg-well">
            <div className="h-full rounded-full bg-[linear-gradient(90deg,#2f7eef,#8c3ae9)] transition-all duration-700" style={{ width: `${Math.max(4, ov.job.progress)}%` }} />
          </div>
        </div>
      )}
      {!ov.job && ov.restart.required && (
        <Notice tone="warn" icon="warntriangle" title="Restart to load your mod changes"
          body={ov.restart.changed.length > 0 ? <span className="line-clamp-1">{ov.restart.changed.slice(0, 6).join(" · ")}</span> : undefined}
          action={<button type="button" onClick={restartNow} disabled={restarting || !ov.serverRunning} className="nx-cta px-4 py-1.5 text-[12.5px] disabled:opacity-50">{restarting ? "Restarting…" : "Restart now"}</button>} />
      )}
      {!unavailable && !ov.installsLive && (
        <Notice tone="warn" icon="lock" title="One-click mod changes aren't switched on yet"
          body={<>Browse and see what&apos;s installed; installing, updating, switching off or removing from here is paused. Add mods by hand in <strong className="font-semibold text-tx">Files</strong> meanwhile.</>} />
      )}
      {ov.load.level === "high" && cur !== "health" && (
        <Notice tone="warn" icon="warntriangle" title="Heavy for this tier" body={ov.load.headline}
          action={<button type="button" onClick={() => setView("health")} className="text-[12px] font-semibold text-tx underline-offset-2 hover:underline">See Health</button>} />
      )}
      {error && <Notice tone="bad" icon="warncircle" title={error} />}
      {notice && !error && <Notice tone="ok" icon="checkcircle" title={notice} />}

      {/* ── the four views ── */}
      <div className="grid grid-cols-4 gap-1 rounded-[14px] border border-rim-hi bg-surface p-1" role="tablist" aria-label="Mods">
        {tabs.map((t) => {
          const on = cur === t.k;
          return (
            <button key={t.k} type="button" role="tab" id={`mods-tab-${t.k}`} aria-selected={on} aria-controls="mods-view" onClick={() => setView(t.k)}
              className={"relative flex min-w-0 flex-col items-center justify-center gap-0.5 rounded-[10px] px-1.5 py-2 text-center transition sm:flex-row sm:gap-2 sm:px-3 " +
                (on ? "bg-[linear-gradient(120deg,#2f7eef,#8c3ae9)] text-[#fff] shadow-[0_8px_22px_-14px_rgba(140,58,233,.9)]" : "text-tx-dim hover:bg-well hover:text-tx")}>
              <Icon name={t.icon} size={13} tone="inherit" />
              <span className="truncate text-[12px] font-bold sm:text-[13px]">{t.label}</span>
              {t.count !== null && (
                <span className={"num rounded-full px-1.5 text-[10.5px] font-bold leading-[17px] " + (on ? "bg-[#fff]/20 text-[#fff]" : t.dot === "warn" ? "bg-amber/15 text-amber" : t.dot === "info" ? "bg-cyan/15 text-cyan" : "bg-well text-tx-faint")}>{t.count}</span>
              )}
            </button>
          );
        })}
      </div>

      <div id="mods-view" role="tabpanel" aria-labelledby={`mods-tab-${cur}`} className="min-w-0">
        {cur === "installed" && (
          <InstalledLibrary
            ov={ov}
            busy={!!ov.job}
            updates={updates}
            checking={checking}
            onCheckUpdates={doCheckUpdates}
            onUpdate={(m) => run(() => panelUpdateMod(serverId, m.id), `Updating ${m.name}…`)}
            onRemove={(m) => setRemoving(m)}
            onVersions={(m) => setVersionsOf(m)}
            onBrowse={() => setView("browse")}
            onApply={(changes, risky) => (risky.length ? setRiskBatch({ changes, risky }) : applyBatch(changes, false))}
            onTracked={() => { void loadOverview(); setNotice("Queued — the Mods tab manages it from now on."); }}
            serverId={serverId}
          />
        )}
        {cur === "browse" && (
          <ModBrowser
            serverId={serverId}
            scope={scope}
            unavailable={unavailable}
            jobActive={!!ov.job || !ov.installsLive}
            refreshKey={refreshKey}
            defaultCategory={pluginCategory}
            catalogTotal={ov.catalogTotal}
            onInstall={(m) => setConfirm(fromCard(m))}
            onAct={(modId, op) => {
              if (op === "remove") run(() => panelRemoveMod(serverId, modId));
              else if (op === "update") run(() => panelUpdateMod(serverId, modId));
              else if (op === "enable" || op === "disable") setView("installed");
            }}
            onTotal={setTotal}
          />
        )}
        {cur === "updates" && (
          <div className="flex flex-col gap-3">
            {cyrusUpdates.length > 0 && <CyrusUpdates mods={cyrusUpdates} busy={!!ov.job || !ov.installsLive} onOpen={(m) => setVersionsOf(m)} />}
            <AutoUpdatePanel serverId={serverId} hideModIds={installedVisible.filter((m) => m.cyrus).map((m) => m.id)} />
          </div>
        )}
        {cur === "health" && <HealthView ov={ov} onInstalled={() => setView("installed")} />}
      </div>

      {confirm && <InstallDialog serverId={serverId} mod={confirm} load={ov.load} live={ov.installsLive} onCancel={() => setConfirm(null)} onConfirm={(ack) => install(confirm, ack)} />}
      {removing && (
        <RemoveDialog m={removing} onCancel={() => setRemoving(null)}
          onConfirm={() => { const m = removing; setRemoving(null); run(() => panelRemoveMod(serverId, m.id), `Removing ${m.name}…`); }} />
      )}
      {versionsOf && (
        <CyrusVersionsDialog serverId={serverId} mod={versionsOf} busy={!!ov.job || !ov.installsLive} onClose={() => setVersionsOf(null)}
          onQueued={(label) => { setVersionsOf(null); setNotice(`Switching ${versionsOf.name} to ${label} — the old jar is backed up first.`); void loadOverview(); }} />
      )}
      {riskBatch && (
        <RiskDialog
          serverId={serverId}
          ov={ov}
          risky={riskBatch.risky}
          count={riskBatch.changes.length}
          onCancel={() => setRiskBatch(null)}
          onConfirm={() => applyBatch(riskBatch.changes, true)}
          onBackedUp={() => void loadOverview()}
        />
      )}
    </div>
  );
}

