type Filter = "all" | "enabled" | "disabled" | "attention";
export type StagedOp = "disable" | "enable";

export function InstalledLibrary({
  ov,
  busy,
  updates,
  checking,
  onCheckUpdates,
  onUpdate,
  onRemove,
  onApply,
  onVersions,
  onBrowse,
  onTracked,
  serverId,
}: {
  ov: ModsOverview;
  busy: boolean;
  updates: Record<string, string | null> | null;
  checking: boolean;
  onCheckUpdates: () => void;
  onUpdate: (m: InstalledMod) => void;
  onRemove: (m: InstalledMod) => void;
  onApply: (changes: { modId: string; op: StagedOp }[], risky: InstalledMod[]) => void;
  /** Cyrus mods: open version history / update / rollback. */
  onVersions: (m: InstalledMod) => void;
  onBrowse: () => void;
  onTracked: () => void;
  serverId: string;
}) {
  const [filter, setFilter] = useState<Filter>("all");
  const [q, setQ] = useState("");
  const [staged, setStaged] = useState<Record<string, StagedOp>>({});
  const [howOpen, setHowOpen] = useState(false);
  const [tracking, setTracking] = useState<string | null>(null);
  const [trackErr, setTrackErr] = useState<string | null>(null);

  const mods = useMemo(() => ov.installed.filter((m) => m.status !== "REMOVED"), [ov.installed]);
  const attention = (m: InstalledMod) => m.status === "FAILED" || m.health?.status === "error" || m.health?.status === "not-seen" || hasUpdateFor(m, updates);
  const counts = {
    all: mods.length,
    enabled: mods.filter((m) => m.status === "INSTALLED").length,
    disabled: mods.filter((m) => m.status === "DISABLED").length,
    attention: mods.filter(attention).length,
  };
  const shown = mods
    .filter((m) => (filter === "enabled" ? m.status === "INSTALLED" : filter === "disabled" ? m.status === "DISABLED" : filter === "attention" ? attention(m) : true))
    .filter((m) => !q.trim() || m.name.toLowerCase().includes(q.trim().toLowerCase()));

  const stagedList = Object.entries(staged).map(([modId, op]) => ({ modId, op }));
  const plan = useMemo(() => {
    const graph = Object.fromEntries(mods.map((m) => [m.id, m.dependsOnIds]));
    const enabled = new Set(mods.filter((m) => m.status === "INSTALLED").map((m) => m.id));
    const names = Object.fromEntries(mods.map((m) => [m.id, m.name]));
    return planToggles(stagedList, graph, enabled, names);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [staged, mods]);
  const risky = mods.filter((m) => staged[m.id] === "disable" && m.toggle.allowed && m.toggle.needsAck);

  const stage = (m: InstalledMod, wantOn: boolean) => {
    setStaged((s) => {
      const next = { ...s };
      const isOn = m.status === "INSTALLED";
      if (wantOn === isOn) delete next[m.id];
      else next[m.id] = wantOn ? "enable" : "disable";
      return next;
    });
  };

  const track = async (buildId: string) => {
    setTracking(buildId);
    setTrackErr(null);
    const r = await trackCyrusInstall(serverId, buildId).catch(() => ({ error: "Couldn't reach the server." }));
    setTracking(null);
    if (r.error) setTrackErr(r.error);
    else onTracked();
  };

  const pol = ov.togglePolicy;
  const anyToggle = mods.some((m) => m.toggle.allowed);
  const blocked = busy || !ov.installsLive;

  const untracked = ov.untrackedCyrus.length > 0 && (
    <div className="flex flex-col gap-2 rounded-[14px] border border-violet/35 bg-violet/[0.06] px-3.5 py-3" data-testid="cyrus-untracked">
      <div className="flex flex-wrap items-center gap-2">
        <CyrusBadge size="xs" />
        <p className="min-w-0 flex-1 text-[12.5px] font-bold text-tx">Cyrus mods copied here before the Mods tab tracked them</p>
      </div>
      <p className="text-[12px] leading-relaxed text-tx-dim">These went onto the server by an earlier install. Manage them here to switch them off, update or roll back: we back up the old copy and reinstall the same version through the mod engine.</p>
      <ul className="flex flex-col gap-1.5">
        {ov.untrackedCyrus.map((u) => (
          <li key={u.buildId} className="flex flex-wrap items-center gap-2 rounded-[10px] border border-rim-hi bg-surface px-3 py-2">
            <span className="min-w-0 flex-1 truncate text-[12.5px] font-semibold text-tx">{u.name}{u.version ? <span className="num ml-1.5 font-normal text-tx-faint">v{u.version}</span> : null}</span>
            <span className="text-[11px] text-tx-faint">copied {new Date(u.at).toLocaleDateString()}</span>
            <button type="button" onClick={() => track(u.buildId)} disabled={blocked || tracking !== null} className={btnGhost}>{tracking === u.buildId ? "Queuing…" : "Manage here"}</button>
          </li>
        ))}
      </ul>
      {trackErr && <p className="text-[12px] text-rose" role="alert">{trackErr}</p>}
    </div>
  );

  if (mods.length === 0) {
    return (
      <div className="flex flex-col gap-3">
        {untracked}
        <div className="flex flex-col items-center gap-2 rounded-[14px] border border-rim-hi bg-surface px-5 py-12 text-center">
          <Icon name="layers" size={24} />
          <p className="text-[14px] font-bold text-tx">No mods installed yet</p>
          <p className="max-w-[50ch] text-[12.5px] leading-relaxed text-tx-dim">Everything you install shows up here with its version, health and an off switch where this game supports one.</p>
          <button type="button" onClick={onBrowse} className="nx-cta mt-2 px-4 py-2 text-[12.5px]">Browse the store</button>
        </div>
      </div>
    );
  }

  return (
    <section aria-label="Installed mods" className="flex flex-col gap-3">
      {untracked}

      {/* toolbar: filters · search · how on/off works · check for updates */}
      <div className="flex flex-wrap items-center gap-2">
        <div className="flex max-w-full flex-wrap gap-1 rounded-[11px] border border-rim-hi bg-surface p-1" role="group" aria-label="Filter installed mods">
          {([["all", "All"], ["enabled", "On"], ["disabled", "Off"], ["attention", "Needs a look"]] as const).map(([k, label]) => (
            <button key={k} type="button" onClick={() => setFilter(k)} aria-pressed={filter === k}
              className={"rounded-[8px] px-2.5 py-1.5 text-[12px] font-semibold transition " + (filter === k ? "bg-violet/15 text-tx" : "text-tx-dim hover:text-tx")}>
              {label} <span className="num text-tx-faint">{counts[k]}</span>
            </button>
          ))}
        </div>
        {mods.length > 6 && (
          <label className="flex h-[36px] min-w-[150px] flex-1 items-center gap-2 rounded-[11px] border border-rim-hi bg-surface px-3 focus-within:border-violet/60 sm:max-w-[240px]">
            <Icon name="search" size={12} tone="inherit" className="text-tx-faint" />
            <span className="sr-only">Find an installed mod</span>
            <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Find installed…" className="min-w-0 flex-1 bg-transparent text-[12.5px] text-tx outline-none placeholder:text-tx-faint" maxLength={60} />
          </label>
        )}
        <div className="ml-auto flex items-center gap-2">
          {pol.safety !== "NOT_SUPPORTED" && anyToggle && (
            <button type="button" onClick={() => setHowOpen((v) => !v)} aria-expanded={howOpen} className={btnGhost + " flex items-center gap-1.5"}>
              <Icon name={pol.safety === "SAFE" ? "shieldcheck" : "shield"} size={12} tone="inherit" /> How on/off works
            </button>
          )}
          {ov.coverage.canUpdate && (
            <button type="button" onClick={onCheckUpdates} disabled={checking} className={btnGhost + " flex items-center gap-1.5"}>
              <Icon name="refresh2" size={12} tone="inherit" /> {checking ? "Checking…" : "Check for updates"}
            </button>
          )}
        </div>
      </div>

      {/* how toggling works on THIS game — straight from the vetting; folded away until asked */}
      {(howOpen || pol.safety === "NOT_SUPPORTED") && (
        <div className="flex items-start gap-3 rounded-[12px] border border-rim-hi bg-well px-3.5 py-3 text-[12px] leading-relaxed text-tx-dim">
          <Icon name={pol.safety === "NOT_SUPPORTED" ? "lock" : pol.safety === "SAFE" ? "shieldcheck" : "shield"} size={13} tone="inherit" className={"mt-0.5 flex-none " + (pol.safety === "SAFE" ? "text-mint" : pol.safety === "SAFE_WITH_WARNING" ? "text-amber" : "text-tx-faint")} />
          <div className="min-w-0">
            {pol.safety === "NOT_SUPPORTED" ? (
              <p><strong className="font-semibold text-tx">On / off isn&apos;t available for {ov.familyName}.</strong> {pol.note}</p>
            ) : (
              <>
                <p>
                  <strong className="font-semibold text-tx">Switching a mod off keeps it installed.</strong> {pol.how}{" "}
                  {pol.restart === "hot" ? "It takes effect within seconds — no restart needed." : "It takes effect when the server restarts."}
                </p>
                {pol.note && <p className="mt-1 text-tx-faint">{pol.note}</p>}
              </>
            )}
          </div>
        </div>
      )}

      {/* rows */}
      <ul className="flex flex-col gap-2">
        {shown.map((m) => (
          <InstalledRow key={m.id} m={m} ov={ov} busy={blocked} latest={latestFor(m, updates)} checked={!!updates && m.id in updates} update={hasUpdateFor(m, updates)} staged={staged[m.id]}
            onToggle={(on) => stage(m, on)} onUpdate={() => (m.cyrus ? onVersions(m) : onUpdate(m))} onRemove={() => onRemove(m)} onVersions={() => onVersions(m)} />
        ))}
        {shown.length === 0 && <li className="rounded-[12px] border border-rim-hi bg-surface px-4 py-6 text-center text-[12.5px] text-tx-faint">Nothing here matches that filter.</li>}
      </ul>

      {ov.depsKnownAt === null && anyToggle && (
        <p className="text-[11.5px] leading-relaxed text-tx-faint">Which mods depend on each other is read from your server after the next mod change; until then the server itself still refuses a change that would break a dependency.</p>
      )}

      {/* staged changes bar */}
      {stagedList.length > 0 && (
        <div className="nx-dark-island sticky bottom-3 z-10 flex flex-col gap-2 rounded-[15px] border border-[#7b3fef]/50 bg-[linear-gradient(140deg,rgba(60,30,150,.94),rgba(10,22,60,.97))] p-3.5 shadow-[0_18px_50px_-20px_rgba(123,63,239,.7)] backdrop-blur" role="region" aria-label="Pending mod changes">
          <div className="flex flex-wrap items-center gap-2.5">
            <Icon name="sliders" size={14} tone="inherit" className="text-cyan-300" />
            <p className="min-w-0 flex-1 text-[13px] font-bold text-white">
              {stagedList.length} change{stagedList.length === 1 ? "" : "s"} ready
              <span className="ml-2 font-normal text-white/65">
                {stagedList.filter((c) => c.op === "disable").length ? `${stagedList.filter((c) => c.op === "disable").length} off` : ""}
                {stagedList.filter((c) => c.op === "disable").length && stagedList.filter((c) => c.op === "enable").length ? " · " : ""}
                {stagedList.filter((c) => c.op === "enable").length ? `${stagedList.filter((c) => c.op === "enable").length} on` : ""}
                {pol.restart === "restart" ? " · restart to apply" : ""}
              </span>
            </p>
            <button type="button" onClick={() => setStaged({})} className="rounded-[10px] px-3 py-1.5 text-[12px] font-semibold text-white/70 transition hover:text-white">Discard</button>
            <button
              type="button"
              disabled={!plan.ok || blocked}
              onClick={() => { onApply(plan.order, risky); setStaged({}); }}
              className="nx-cta px-4 py-2 text-[12.5px] disabled:opacity-50"
            >
              Apply changes
            </button>
          </div>
          {!plan.ok && (
            <ul className="flex flex-col gap-1" role="alert">
              {plan.problems.map((p) => <li key={p} className="flex items-start gap-1.5 text-[12px] leading-snug text-amber-200"><Icon name="warncircle" size={11} tone="inherit" className="mt-0.5 flex-none" />{p}</li>)}
            </ul>
          )}
          {plan.ok && risky.length > 0 && (
            <p className="text-[12px] leading-snug text-amber-200/90">{risky.length === 1 ? `${risky[0].name} may add things to your world` : `${risky.length} of these may add things to your world`} — you&apos;ll be asked to confirm and offered a backup first.</p>
          )}
        </div>
      )}
    </section>
  );
}

function InstalledRow({
  m, ov, busy, latest, checked, update, staged, onToggle, onUpdate, onRemove, onVersions,
}: {
  m: InstalledMod; ov: ModsOverview; busy: boolean; latest: string | null | undefined; checked: boolean; update: boolean; staged: StagedOp | undefined;
  onToggle: (on: boolean) => void; onUpdate: () => void; onRemove: () => void; onVersions: () => void;
}) {
  const st = m.status ? STATE[m.status] : null;
  const pending = !!m.status && PENDING.has(m.status);
  const restable = m.status === "INSTALLED" || m.status === "DISABLED";
  const isOn = staged ? staged === "enable" : m.status === "INSTALLED";
  const cfg = modConfigFolder(ov.family, ov.variant);
  const h = m.health && m.status === "INSTALLED" ? HEALTH[m.health.status] : null;
  const size = fileSize(m.fileBytes);
  const t = m.toggle;
  const cy = m.cyrus;
  return (
    <li className={"flex flex-col gap-2.5 rounded-[14px] border p-3.5 transition sm:flex-row sm:items-center " + (staged ? "border-violet/55 bg-violet/[0.07]" : "border-rim-hi bg-surface") + (m.status === "DISABLED" && !staged ? " opacity-80" : "")} data-cyrus={cy ? "1" : undefined}>
      <div className="flex min-w-0 flex-1 items-start gap-3">
        <ModIcon m={m} size={38} />
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-1.5">
            <span className="truncate text-[13.5px] font-bold text-tx">{m.name}</span>
            {cy && <CyrusBadge size="xs" />}
            {st && <Chip cls={st.cls}>{st.label}</Chip>}
            {staged && <Chip cls="border-cyan/45 bg-cyan/10 text-cyan" icon="sliders">{staged === "enable" ? "Will enable" : "Will disable"}</Chip>}
            {h && <Chip cls={h.cls} icon={h.icon} title={`${h.tip}${m.health?.evidence ? ` — ${m.health.evidence}` : ""} (checked ${new Date(m.health!.checkedAt).toLocaleString()})`}>{h.label}</Chip>}
            {update && <Chip cls="border-cyan/40 bg-cyan/10 text-cyan" icon="bolt">{cy ? `${cy.latestLabel} available` : `Update ${latest}`}</Chip>}
            {m.pinned && <Chip cls="border-rim-hi bg-well text-tx-dim" icon="pin" title="Pinned: never auto-updated">Pinned</Chip>}
            {restable && t.allowed && t.contentRisk && <Chip cls="border-amber/35 bg-amber/[0.07] text-amber" icon="warncircle" title={t.warning ?? undefined}>Adds content</Chip>}
          </div>
          <p className="mt-0.5 flex flex-wrap gap-x-2 text-[11.5px] text-tx-faint">
            {cy ? (cy.installedLabel ? <span className="num">{cy.installedLabel}</span> : m.version && <span className="num">v{m.version}</span>) : m.version && <span className="num">v{m.version}</span>}
            <span>{cy ? "Made with Cyrus" : SOURCE_LABEL[m.source] ?? m.source}</span>
            {cy && <span>{cy.versionCount} version{cy.versionCount === 1 ? "" : "s"}</span>}
            {size && <span title="Download size listed by the source">{size}</span>}
            {m.installedAt && <span>added {new Date(m.installedAt).toLocaleDateString()}</span>}
            {!cy && checked && latest === null && m.version && <span>couldn&apos;t check for updates</span>}
            {!cy && latest && !update && m.version && <span>up to date</span>}
            {cy && !update && cy.installedBuildId && <span>latest version</span>}
          </p>
          {(m.dependsOn.length > 0 || m.neededBy.length > 0) && (
            <p className="mt-1 flex flex-wrap gap-x-3 gap-y-0.5 text-[11.5px] text-tx-dim">
              {m.dependsOn.length > 0 && <span className="inline-flex items-center gap-1"><Icon name="link" size={10} tone="inherit" className="text-tx-faint" />Needs {m.dependsOn.join(", ")}</span>}
              {m.neededBy.length > 0 && <span className="inline-flex items-center gap-1"><Icon name="nodes" size={10} tone="inherit" className="text-tx-faint" />Needed by {m.neededBy.join(", ")}</span>}
            </p>
          )}
          {m.error && <p className="mt-1 text-[11.5px] leading-snug text-rose">{m.error}</p>}
          {staged === "disable" && t.allowed && t.warning && <p className="mt-1 text-[11.5px] leading-snug text-amber">{t.warning}</p>}
        </div>
      </div>
      <div className="flex flex-none flex-wrap items-center gap-2 sm:justify-end">
        {pending && <span className="text-[11.5px] text-cyan">{st?.label}…</span>}
        {ov.coverage.canUpdate && m.status === "INSTALLED" && update && (
          <button type="button" disabled={busy || pending} onClick={onUpdate} className={btnGhost}>{cy ? "Update" : "Update"}</button>
        )}
        {cy && restable && (
          <button type="button" onClick={onVersions} className={btnGhost + " flex items-center gap-1.5"} title="Version history, notes and rollback">
            <Icon name="clock" size={11} tone="inherit" /> Versions
          </button>
        )}
        {cfg && restable && (
          <button type="button" onClick={() => goPanelTab("files", cfg)} className={btnGhost} title="Open the folder where this game keeps mod settings">Config</button>
        )}
        {(restable || m.status === "FAILED") && (
          <button type="button" disabled={busy || pending} onClick={onRemove}
            className="rounded-[10px] border border-rim-hi px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:border-rose/50 hover:text-rose disabled:opacity-50">
            {m.status === "FAILED" ? "Clear" : "Uninstall"}
          </button>
        )}
        {restable && t.allowed && (
          <Switch on={isOn} disabled={busy || pending} onChange={onToggle} label={isOn ? `Disable ${m.name}` : `Enable ${m.name}`} />
        )}
        {restable && !t.allowed && ov.togglePolicy.safety !== "NOT_SUPPORTED" && (
          <span title={t.reason} className="inline-flex cursor-help items-center gap-1 text-[11px] text-tx-faint"><Icon name="lock" size={10} tone="inherit" />No off switch</span>
        )}
      </div>
    </li>
  );
}

