"use client";

import { Icon } from "@/components/nx/Icon";
import type { InstalledMod, ModsOverview } from "@/lib/actions-mod-installs";
import type { ModLoad } from "@/lib/mod-load";
import { CyrusBadge } from "@/components/nx/CyrusBadge";

/**
 * Mods tab → Health. Everything that answers "is my modded server OK?" in one
 * place, read from real facts only: the load estimate for this tier
 * (lib/mod-load.ts), the last per-mod verdict from the game log
 * (worker/mod-health.ts → ModUpdateRun trigger "health"), installs that failed
 * with their reason, the dependency graph the worker published, and where
 * backups and hand-installed files live.
 */

export function healthIssues(ov: ModsOverview) {
  const mods = ov.installed.filter((m) => m.status !== "REMOVED");
  const failed = mods.filter((m) => m.status === "FAILED");
  const errors = mods.filter((m) => m.status === "INSTALLED" && m.health?.status === "error");
  const notSeen = mods.filter((m) => m.status === "INSTALLED" && m.health?.status === "not-seen");
  const loadHigh = ov.load.level === "high";
  return { failed, errors, notSeen, loadHigh, count: failed.length + errors.length + notSeen.length + (loadHigh ? 1 : 0) };
}

const card = "rounded-[14px] border border-rim-hi bg-surface p-4";

const LOAD_STYLE: Record<string, { ring: string; ink: string; icon: string; label: string }> = {
  fine: { ring: "border-rim-hi bg-surface", ink: "text-mint", icon: "checkcircle", label: "Load looks fine" },
  watch: { ring: "border-cyan/35 bg-cyan/[0.06]", ink: "text-cyan", icon: "warncircle", label: "Worth watching" },
  high: { ring: "border-amber/45 bg-amber/[0.08]", ink: "text-amber", icon: "warntriangle", label: "Heavy for this tier" },
};

export function LoadCard({ load }: { load: ModLoad }) {
  const st = LOAD_STYLE[load.level];
  return (
    <div className={"flex flex-wrap items-start gap-3.5 rounded-[14px] border px-4 py-3.5 " + st.ring}>
