  );
}

const VERDICT: Record<string, { label: string; cls: string; icon: string }> = {
  error: { label: "Load error", cls: "text-rose", icon: "warntriangle" },
  "not-seen": { label: "Not seen in log", cls: "text-amber", icon: "warncircle" },
  loaded: { label: "Loaded", cls: "text-mint", icon: "checkcircle" },
  unknown: { label: "Unknown", cls: "text-tx-faint", icon: "warncircle" },
};

function HealthRow({ m }: { m: InstalledMod }) {
  const v = VERDICT[m.health?.status ?? "unknown"];
  return (
    <li className="flex flex-col gap-1 py-2.5 sm:flex-row sm:items-center sm:gap-3">
      <span className="flex min-w-0 flex-1 items-center gap-2">
        <span className="truncate text-[13px] font-semibold text-tx">{m.name}</span>
        {m.cyrus && <CyrusBadge size="xs" sealOnly />}
      </span>
      {m.health?.evidence && <span className="min-w-0 truncate font-mono text-[11px] text-tx-faint sm:max-w-[46%]" title={m.health.evidence}>{m.health.evidence}</span>}
      <span className={"inline-flex flex-none items-center gap-1 text-[12px] font-bold " + v.cls}><Icon name={v.icon} size={11} tone="inherit" />{v.label}</span>
    </li>
  );
}

export function HealthView({ ov, onInstalled }: { ov: ModsOverview; onInstalled: () => void }) {
  const mods = ov.installed.filter((m) => m.status !== "REMOVED");
  const { failed, errors, notSeen } = healthIssues(ov);
  const checked = mods.map((m) => m.health?.checkedAt).filter((x): x is string => !!x).sort().pop() ?? null;
  const withVerdict = mods.filter((m) => m.status === "INSTALLED" && m.health);
  const order = (m: InstalledMod) => (m.health?.status === "error" ? 0 : m.health?.status === "not-seen" ? 1 : 2);
  const deps = mods.filter((m) => m.dependsOn.length > 0);

  return (
    <div className="flex flex-col gap-3" data-testid="mods-health">
      <LoadCard load={ov.load} />

      <section className={card} aria-label="Mod health">
        <div className="flex flex-wrap items-baseline justify-between gap-2">
          <h3 className="text-[14px] font-bold text-tx">Did each mod load?</h3>
          <p className="text-[11.5px] text-tx-faint">{checked ? `From the game log, checked ${new Date(checked).toLocaleString()}` : "Not checked yet"}</p>
        </div>
        {withVerdict.length ? (
          <ul className="mt-1 divide-y divide-[var(--color-rim)]">
            {[...withVerdict].sort((a, b) => order(a) - order(b)).map((m) => <HealthRow key={m.id} m={m} />)}
          </ul>
        ) : (
          <p className="mt-2 text-[12.5px] leading-relaxed text-tx-dim">
            After the server starts with mods installed, we read its log and mark each mod as loaded, errored or missing. {mods.length ? "Nothing has been read for this server yet — it happens after the next start." : "Install a mod to see it here."}
          </p>
        )}
        {(errors.length > 0 || notSeen.length > 0) && (
          <p className="mt-2 text-[12px] leading-relaxed text-tx-faint">A mod that errors or never shows up usually needs a different version for this server, or a dependency. The full log is in <strong className="font-semibold text-tx-dim">Console</strong>.</p>
        )}
      </section>

      {failed.length > 0 && (
        <section className={card} aria-label="Failed changes">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <h3 className="text-[14px] font-bold text-tx">Changes that didn&apos;t go through</h3>
            <button type="button" onClick={onInstalled} className="text-[12px] font-semibold text-violet hover:underline">Open Installed</button>
          </div>
          <ul className="mt-2 flex flex-col gap-2">
            {failed.map((m) => (
              <li key={m.id} className="rounded-[11px] border border-rose/30 bg-rose/[0.06] px-3 py-2.5">
                <p className="text-[12.5px] font-bold text-tx">{m.name}</p>
                {m.error && <p className="mt-0.5 text-[12px] leading-relaxed text-rose">{m.error}</p>}
              </li>
            ))}
          </ul>
          <p className="mt-2 text-[11.5px] text-tx-faint">Nothing was changed on the server for these. Clear them from Installed, or try again.</p>
        </section>
      )}

      <section className={card} aria-label="Dependencies">
        <h3 className="text-[14px] font-bold text-tx">Dependencies</h3>
        {deps.length ? (
          <ul className="mt-2 flex flex-col gap-1.5 text-[12.5px] text-tx-dim">
            {deps.map((m) => <li key={m.id}><strong className="font-semibold text-tx">{m.name}</strong> needs {m.dependsOn.join(", ")}</li>)}
          </ul>
        ) : (
          <p className="mt-1.5 text-[12.5px] text-tx-dim">{mods.length ? "No installed mod needs another one." : "Nothing installed."}</p>
        )}
        <p className="mt-2 text-[11.5px] text-tx-faint">{ov.depsKnownAt ? `Read from the server after the mod change on ${new Date(ov.depsKnownAt).toLocaleString()}.` : "Read from the server after the next mod change. Until then the server itself refuses a change that would break a dependency."}</p>
      </section>

      <section className={card} aria-label="Manual installs and backups">
        <h3 className="text-[14px] font-bold text-tx">Manual installs &amp; backups</h3>
        <p className="mt-1.5 text-[12.5px] leading-relaxed text-tx-dim">
          Anything not in the store can still be installed by hand: upload it in the <strong className="font-semibold text-tx">Files</strong> tab and restart from <strong className="font-semibold text-tx">Console</strong>.
          Before changing files we keep a backup on your server in <span className="font-mono text-tx">/root/.nxeon-mods/backups</span> (the last five changes).
        </p>
        {ov.lastWorldBackupAt && <p className="mt-1.5 text-[11.5px] text-tx-faint">Last world backup from this panel: {new Date(ov.lastWorldBackupAt).toLocaleString()}.</p>}
      </section>
    </div>
  );
}

