input.content:
"use client";

import { useEffect, useState } from "react";
import { Icon } from "@/components/nx/Icon";
import type { InstalledMod } from "@/lib/actions-mod-installs";
import { getCyrusVersions, switchCyrusVersion } from "@/lib/actions-cyrus-installed";
import type { CyrusVersionRow } from "@/lib/cyrus-mods/installed";
import { CyrusBadge } from "@/components/nx/CyrusBadge";

/**
 * Mods tab → a Cyrus mod's versions: every finished version with its release
 * notes (the builder's own "what changed", else the change that was asked
 * for), which one is on this server, "Update to latest" and rollback to any
 * earlier version. A switch is one engine job (old jar backed up first).
 */
export function CyrusVersionsDialog({ serverId, mod, busy, onClose, onQueued }: {
  serverId: string; mod: InstalledMod; busy: boolean; onClose: () => void; onQueued: (label: string) => void;
}) {
  const [data, setData] = useState<Awaited<ReturnType<typeof getCyrusVersions>> | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [working, setWorking] = useState<string | null>(null);
  const [confirm, setConfirm] = useState<CyrusVersionRow | null>(null);

  useEffect(() => {
    let live = true;
    getCyrusVersions(serverId, mod.id).then((r) => live && setData(r)).catch(() => live && setData({ error: "Couldn't load this mod's versions." }));
    return () => { live = false; };
  }, [serverId, mod.id]);
  useEffect(() => {
    const k = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [onClose]);

  const versions = data?.versions ?? [];
  const installed = versions.find((v) => v.installed) ?? null;
  const latest = versions.find((v) => v.latest) ?? null;
  const installedIdx = installed ? versions.indexOf(installed) : -1;

  const go = async (v: CyrusVersionRow) => {
    setConfirm(null);
    setWorking(v.buildId);
    setErr(null);
    const r = await switchCyrusVersion(serverId, mod.id, v.buildId).catch(() => ({ error: "Couldn't reach the server." }));
    setWorking(null);
    if (r.error) setErr(r.error);
    else onQueued(v.label);
  };
  const disabled = busy || !data?.canSwitch || working !== null;

  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-black/65 p-4 backdrop-blur-sm" role="dialog" aria-modal="true" aria-label={`${mod.name} versions`} onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="nx-dark-island flex max-h-[88vh] w-full max-w-[560px] flex-col overflow-hidden rounded-[17px] border border-[#7b3fef]/40 bg-[linear-gradient(180deg,rgba(14,26,56,.98),rgba(3,9,24,.99))]">
        <div className="flex items-start gap-3 border-b border-white/10 p-5 pb-4">
          <div className="min-w-0 flex-1">
            <div className="flex flex-wrap items-center gap-2">
              <h3 className="text-[16px] font-extrabold text-white">{mod.name}</h3>
              <CyrusBadge size="xs" tone="onDark" />
            </div>
            <p className="mt-1 text-[12px] text-white/60">
              {installed ? <>On this server: <strong className="font-semibold text-white">{installed.label}</strong></> : "Installed version unknown"}
              {latest && installed && latest.buildId !== installed.buildId && <> · latest <strong className="font-semibold text-cyan-200">{latest.label}</strong></>}
            </p>
          </div>
          <button type="button" onClick={onClose} aria-label="Close" className="rounded-[9px] p-1.5 text-white/60 hover:bg-white/10 hover:text-white"><Icon name="xcircle" size={16} tone="inherit" /></button>
        </div>

        <div className="min-h-0 flex-1 overflow-y-auto p-5 pt-4">
          {!data && <p className="flex items-center gap-2 text-[12.5px] text-white/70"><Icon name="refresh" size={12} tone="inherit" className="animate-spin" /> Loading versions…</p>}
          {data?.error && <p className="text-[12.5px] text-red-300">{data.error}</p>}

          {latest && installed && latest.buildId !== installed.buildId && (
            <div className="mb-4 flex flex-wrap items-center gap-3 rounded-[13px] border border-cyan-400/35 bg-cyan-400/[0.08] px-3.5 py-3">
              <Icon name="bolt" size={14} tone="inherit" className="text-cyan-200" />
              <p className="min-w-0 flex-1 text-[12.5px] text-cyan-100"><strong className="font-bold">{latest.label}</strong> is newer than what&apos;s on this server.</p>
              <button type="button" onClick={() => setConfirm(latest)} disabled={disabled} className="nx-cta px-4 py-1.5 text-[12.5px] disabled:opacity-50">{working === latest.buildId ? "Queuing…" : "Update to latest"}</button>
            </div>
          )}
          {data?.why && <p className="mb-3 rounded-[10px] border border-amber-500/30 bg-amber-500/[0.08] px-3 py-2 text-[12px] text-amber-200">{data.why}</p>}
          {err && <p className="mb-3 rounded-[10px] border border-red-500/35 bg-red-500/10 px-3 py-2 text-[12px] text-red-300" role="alert">{err}</p>}

          <h4 className="text-[10.5px] font-bold uppercase tracking-[0.14em] text-white/50">Version history</h4>
          <ol className="mt-2 flex flex-col">
            {versions.map((v, i) => (
              <li key={v.buildId} className="relative flex gap-3 pb-4 last:pb-0">
                <span className="relative flex w-3 flex-none justify-center" aria-hidden>
                  <span className={"mt-1.5 h-2.5 w-2.5 rounded-full border-2 " + (v.installed ? "border-cyan-300 bg-cyan-300" : "border-white/35 bg-transparent")} />
                  {i < versions.length - 1 && <span className="absolute top-5 bottom-[-6px] w-px bg-white/15" />}
                </span>
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-1.5">
                    <span className="num text-[13px] font-bold text-white">{v.label}</span>
                    {v.installed && <span className="rounded-[5px] border border-cyan-300/45 bg-cyan-300/10 px-1.5 py-0.5 text-[9.5px] font-bold uppercase tracking-wide text-cyan-200">On this server</span>}
                    {v.latest && <span className="rounded-[5px] border border-white/20 bg-white/[0.06] px-1.5 py-0.5 text-[9.5px] font-bold uppercase tracking-wide text-white/75">Latest</span>}
                    {v.safety === "warn" && <span className="rounded-[5px] border border-amber-400/40 bg-amber-400/10 px-1.5 py-0.5 text-[9.5px] font-bold uppercase tracking-wide text-amber-200">Safety notes</span>}
                    <span className="text-[11px] text-white/45">{new Date(v.at).toLocaleDateString()} · MC {v.mcVersion}</span>
                  </div>
                  <p className="mt-1 whitespace-pre-line text-[12.5px] leading-relaxed text-white/80">{v.notes}</p>
                  {v.request && v.request !== v.notes && <p className="mt-1 line-clamp-2 text-[11.5px] italic leading-snug text-white/45" title={v.request}>Asked for: {v.request}</p>}
                  {!v.installed && (
                    <button type="button" onClick={() => setConfirm(v)} disabled={disabled}
                      className="mt-2 rounded-[9px] border border-white/15 bg-white/[0.05] px-2.5 py-1 text-[11.5px] font-semibold text-white/80 transition hover:border-white/30 hover:text-white disabled:opacity-45">
                      {working === v.buildId ? "Queuing…" : installedIdx >= 0 && i > installedIdx ? "Roll back to this" : "Switch to this"}
                    </button>
                  )}
                </div>
              </li>
            ))}
          </ol>
        </div>

        <div className="flex flex-wrap items-center gap-3 border-t border-white/10 px-5 py-3">
