import { NextResponse } from "next/server";
import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import { join } from "node:path";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { cyrusAccessFor, pageVisibleTo } from "@/lib/cyrus-mods/gate";
import { licenseText, readModDoc } from "@/lib/cyrus-mods/doc";
import { displayUser } from "@/lib/cyrus-mods/pages";
import { serviceBuildId } from "@/lib/cyrus-mods/registry";
import { svcSourceZip } from "@/lib/modbuilder/client";
import { MODBUILD_DIR, readJar } from "@/lib/modbuilder/store";
import { readZip } from "@/lib/mods/archive";
import { writeZip } from "@/lib/mod-autoupdate/zip";
import { checkRateLimit } from "@/lib/rate-limit";

export const dynamic = "force-dynamic";

const NF = () => NextResponse.json({ error: "Not found" }, { status: 404, headers: { "x-robots-tag": "noindex" } });

/**
 * Cyrus mod downloads (gated like the page): ?what=source|jar&build=<id>.
 * Source = the build's source tree from the build service (cached on the
 * primary after the first fetch) plus LICENSE (the page's licence) and
 * NXEON-CYRUS.md (what it is, version, where it came from). Every Cyrus mod is
 * open source; the creator picks the licence (default MIT).
 */
export async function GET(req: Request, { params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  let user = null;
  try { user = await currentUser(); } catch { user = null; }
  if (!(await cyrusAccessFor(user)).allowed) return NF();
  if (!/^[a-z0-9-]{3,60}$/.test(slug)) return NF();
  const page = await db.cyrusModPage.findUnique({ where: { slug } });
  if (!page || !pageVisibleTo(page, user)) return NF();
  const doc = readModDoc(page.doc);
  const url = new URL(req.url);
  const buildId = url.searchParams.get("build") || doc?.currentBuildId || "";
  const what = url.searchParams.get("what") === "jar" ? "jar" : "source";
  const v = doc?.versions.find((x) => x.buildId === buildId);
  if (!v) return NF();
  const ip = req.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || "anon";
  const rl = checkRateLimit(`cyrusdl:${user?.id ?? ip}`, { max: 30, windowMs: 10 * 60_000 });
  if (!rl.ok) return NextResponse.json({ error: `Too many downloads. Retry in ${rl.retryAfterSec}s.` }, { status: 429 });
  const build = await db.modBuild.findUnique({ where: { id: buildId } });
  if (!build || (build.rootBuildId ?? build.id) !== page.rootBuildId || build.status !== "succeeded") return NF();
  const base = (build.pluginName || "plugin").replace(/[^A-Za-z0-9_]/g, "") || "plugin";
  const ver = (build.version || "source").replace(/[^A-Za-z0-9_.-]/g, "");

  if (what === "jar") {
    let bytes: Buffer;
    try { bytes = await readJar(build); } catch { return NF(); }
    return new Response(new Uint8Array(bytes), {
      headers: { "Content-Type": "application/java-archive", "Content-Length": String(bytes.length), "Content-Disposition": `attachment; filename="${(build.jarName || `${base}.jar`).replace(/[^A-Za-z0-9_.-]/g, "")}"`, "Cache-Control": "private, no-store", "X-Content-Type-Options": "nosniff", "X-Robots-Tag": "noindex" },
    });
  }

  const cache = join(MODBUILD_DIR, `${build.id}.source.zip`);
  let zip: Buffer | null = await readFile(cache).catch(() => null);
  if (!zip) {
    try {
      const r = await svcSourceZip(await serviceBuildId(build.id));
      if (!r.ok) return NF();
      zip = Buffer.from(await r.arrayBuffer());
      await mkdir(MODBUILD_DIR, { recursive: true, mode: 0o750 });
      await writeFile(cache + ".part", zip, { mode: 0o640 });
      await rename(cache + ".part", cache);
    } catch {
      return NextResponse.json({ error: "The source is being fetched from the builder, which is offline right now. Try again shortly." }, { status: 503 });
    }
  }
  let entries;
  try { entries = readZip(zip); } catch { return NextResponse.json({ error: "The stored source archive is unreadable." }, { status: 500 }); }
  const creator = displayUser(await db.user.findUnique({ where: { id: page.userId }, select: { name: true } }));
  const year = (build.finishedAt ?? build.createdAt).getUTCFullYear();
  const readme = `# ${page.title}\n\n${page.tagline ?? ""}\n\nVersion: ${v.version ?? v.n} (v${v.n}) for Minecraft ${v.mcVersion} on Paper / Purpur.\nMade with Cyrus, Nxeon's AI mod studio, by ${creator}.\nLicence: ${page.license} (see LICENSE).\n\nRelease notes:\n${v.notes}\n`;
  const files = entries.filter((e) => !e.dir && !/^(LICENSE|NXEON-CYRUS\.md)$/i.test(e.path.join("/"))).map((e) => ({ name: `${base}/${e.path.join("/")}`, data: e.data }));
  files.push({ name: `${base}/LICENSE`, data: Buffer.from(licenseText(page.license, year, creator)) });
  files.push({ name: `${base}/NXEON-CYRUS.md`, data: Buffer.from(readme) });
  const out = writeZip(files, build.finishedAt ?? build.createdAt);
  return new Response(new Uint8Array(out), {
    headers: { "Content-Type": "application/zip", "Content-Length": String(out.length), "Content-Disposition": `attachment; filename="${base}-${ver}-source.zip"`, "Cache-Control": "private, no-store", "X-Robots-Tag": "noindex" },
  });
}
