import Link from "next/link";
import { Icon } from "@/components/nx/Icon";
import { CyrusBadge, CyrusSeal } from "@/components/nx/CyrusBadge";
import type { PageView } from "@/lib/cyrus-mods/pages";
import { CYRUS_LICENSES, versionLabel } from "@/lib/cyrus-mods/doc";
import { CyrusModTabs } from "./CyrusModTabs";
import { CyrusCommunity } from "./CyrusCommunity";
import { CyrusOwnerPanel } from "./CyrusOwnerPanel";
import { ForkButton } from "./ForkButton";

/**
 * A Cyrus mod's page — rendered identically in the portal (NxLabs, signed-in)
 * and on the public /mods/cyrus/<slug> route. Every section is generated from
 * the mod's builds (lib/cyrus-mods/doc.ts); nothing is hand-written.
 */
export function CyrusModView({ p, mode, canFork, signedIn }: { p: PageView; mode: "portal" | "public"; canFork: boolean; signedIn: boolean }) {
  const d = p.doc;
  const cur = d.versions.find((v) => v.buildId === d.currentBuildId) ?? d.versions[0];
  const dl = (what: "jar" | "source", build?: string) => `/api/nxlabs/cyrus/${p.slug}/download?what=${what}${build ? `&build=${build}` : ""}`;
  const lic = CYRUS_LICENSES.find((l) => l.id === p.license);
  const base = mode === "portal" ? "/dashboard/nxlabs/cyrus" : "/mods/cyrus";

  const overview = (
    <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_300px]">
      <div className="flex min-w-0 flex-col gap-4">
        {d.summary && (
          <section className="rounded-[16px] border border-rim-hi bg-surface p-5">
            <h2 className="text-[15px] font-extrabold text-tx">What it does</h2>
            <p className="mt-2 whitespace-pre-line text-[13.5px] leading-relaxed text-tx-body">{d.summary}</p>
          </section>
        )}
        {d.howToUse.length > 0 && (
          <section className="rounded-[16px] border border-rim-hi bg-surface p-5">
            <h2 className="text-[15px] font-extrabold text-tx">How to use it</h2>
            <ol className="mt-2.5 flex list-decimal flex-col gap-1.5 pl-5 text-[13px] leading-relaxed text-tx-body">
              {d.howToUse.map((h, i) => <li key={i}>{h}</li>)}
            </ol>
          </section>
        )}
        {d.commands.length > 0 && (
          <section className="rounded-[16px] border border-rim-hi bg-surface p-5" aria-label="Commands">
            <h2 className="text-[15px] font-extrabold text-tx">Commands</h2>
            <div className="mt-2.5 overflow-x-auto">
              <table className="w-full min-w-[480px] text-left text-[12.5px]">
                <thead className="text-[10.5px] uppercase tracking-[0.12em] text-tx-faint"><tr><th className="py-1.5 pr-3 font-bold">Command</th><th className="py-1.5 pr-3 font-bold">What it does</th><th className="py-1.5 font-bold">Who</th></tr></thead>
                <tbody className="divide-y divide-[var(--color-rim)]">
                  {d.commands.map((c) => (
                    <tr key={c.usage}><td className="py-2 pr-3 align-top font-mono text-[12px] text-tx">{c.usage}</td><td className="py-2 pr-3 align-top text-tx-dim">{c.description}</td><td className="py-2 align-top text-tx-faint">{c.whoCanUse}{c.permission ? <span className="block font-mono text-[10.5px]">{c.permission}</span> : null}</td></tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        )}
        {d.permissions.length > 0 && (
          <section className="rounded-[16px] border border-rim-hi bg-surface p-5" aria-label="Permissions">
            <h2 className="text-[15px] font-extrabold text-tx">Permissions</h2>
            <ul className="mt-2 divide-y divide-[var(--color-rim)]">
              {d.permissions.map((x) => (
                <li key={x.node} className="flex flex-col gap-0.5 py-2 sm:flex-row sm:items-baseline sm:gap-3">
                  <span className="font-mono text-[12px] text-tx sm:w-[38%] sm:flex-none">{x.node}</span>
                  <span className="min-w-0 flex-1 text-[12.5px] text-tx-dim">{x.description}</span>
                  <span className="text-[11px] text-tx-faint">default: {x.default}</span>
                </li>
              ))}
            </ul>
          </section>
        )}
        {d.config.length > 0 && (
          <section className="rounded-[16px] border border-rim-hi bg-surface p-5" aria-label="Config">
            <h2 className="text-[15px] font-extrabold text-tx">Config <span className="font-mono text-[11.5px] font-normal text-tx-faint">plugins/{d.pluginName ?? "…"}/config.yml</span></h2>
            <ul className="mt-2 divide-y divide-[var(--color-rim)]">
              {d.config.map((c) => (
                <li key={c.key} className="flex flex-col gap-0.5 py-2 sm:flex-row sm:items-baseline sm:gap-3">
                  <span className="font-mono text-[12px] text-tx sm:w-[38%] sm:flex-none">{c.key}</span>
                  <span className="min-w-0 flex-1 text-[12.5px] text-tx-dim">{c.description}</span>
                  <span className="font-mono text-[11px] text-tx-faint">{c.default}</span>
                </li>
              ))}
            </ul>
          </section>
        )}
        {d.limitations.length > 0 && (
          <section className="rounded-[16px] border border-rim-hi bg-surface p-5">
            <h2 className="text-[15px] font-extrabold text-tx">Good to know</h2>
            <ul className="mt-2 flex list-disc flex-col gap-1 pl-5 text-[12.5px] leading-relaxed text-tx-dim">{d.limitations.map((l, i) => <li key={i}>{l}</li>)}</ul>
          </section>
        )}
      </div>

      <aside className="flex flex-col gap-4">
        <section className="rounded-[16px] border border-rim-hi bg-surface p-4" aria-label="Compatibility">
          <h2 className="text-[13px] font-extrabold text-tx">Runs on</h2>
          <div className="mt-2 flex flex-wrap gap-1.5">
            {d.compat.software.map((s) => <span key={s} className="rounded-[7px] border border-rim-hi bg-well px-2 py-0.5 text-[11.5px] font-semibold text-tx">{s}</span>)}
            {d.compat.mcVersions.map((v) => <span key={v} className="num rounded-[7px] border border-rim-hi bg-well px-2 py-0.5 text-[11.5px] text-tx-dim">MC {v}</span>)}
          </div>
          <p className="mt-2 text-[11.5px] leading-relaxed text-tx-faint">{d.compat.note}</p>
        </section>
        <section className="rounded-[16px] border border-rim-hi bg-surface p-4" aria-label="Open source">
          <h2 className="text-[13px] font-extrabold text-tx">Open source</h2>
          <p className="mt-1.5 text-[12px] leading-relaxed text-tx-dim">Every Cyrus mod ships with its source. This one is under <strong className="font-semibold text-tx">{lic?.label ?? p.license}</strong>{lic ? ` — ${lic.blurb.toLowerCase()}` : ""}</p>
          <div className="mt-3 flex flex-col gap-2">
            <a href={dl("source")} className="flex items-center justify-center gap-1.5 rounded-[11px] border border-rim-hi bg-well px-3 py-2 text-[12.5px] font-semibold text-tx transition hover:border-violet/50" rel="nofollow"><Icon name="download2" size={12} tone="inherit" /> Source (.zip)</a>
            <a href={dl("jar")} className="flex items-center justify-center gap-1.5 rounded-[11px] border border-rim-hi bg-well px-3 py-2 text-[12.5px] font-semibold text-tx transition hover:border-violet/50" rel="nofollow"><Icon name="download" size={12} tone="inherit" /> Plugin (.jar){cur?.jarSize ? <span className="text-tx-faint">· {Math.max(1, Math.round(cur.jarSize / 1024))} KB</span> : null}</a>
          </div>
          {d.files.length > 0 && <p className="mt-2 text-[11px] text-tx-faint">{d.files.length} source file{d.files.length === 1 ? "" : "s"} · LICENSE included</p>}
        </section>
        {cur?.jarSha256 && (
          <section className="rounded-[16px] border border-rim-hi bg-surface p-4">
            <h2 className="text-[13px] font-extrabold text-tx">Checksum</h2>
            <p className="mt-1 break-all font-mono text-[10.5px] text-tx-faint">sha256 {cur.jarSha256}</p>
          </section>
        )}
      </aside>
    </div>
  );

  const versions = (
    <section className="rounded-[16px] border border-rim-hi bg-surface p-5" aria-label="Versions">
      <h2 className="text-[15px] font-extrabold text-tx">Versions &amp; changelog</h2>
      <ol className="mt-3 flex flex-col">
        {d.versions.map((v, i) => (
          <li key={v.buildId} className="relative flex gap-3 pb-5 last:pb-0">
            <span className="relative flex w-3 flex-none justify-center" aria-hidden>
