            {d.compat.mcVersions.map((v) => <span key={v} className="num rounded-[7px] border border-rim-hi bg-well px-2 py-0.5 text-[11.5px] text-tx-dim">MC {v}</span>)}
          </div>
          <p className="mt-2 text-[11.5px] leading-relaxed text-tx-faint">{d.compat.note}</p>
        </section>
        <section className="rounded-[16px] border border-rim-hi bg-surface p-4" aria-label="Open source">
          <h2 className="text-[13px] font-extrabold text-tx">Open source</h2>
          <p className="mt-1.5 text-[12px] leading-relaxed text-tx-dim">Every Cyrus mod ships with its source. This one is under <strong className="font-semibold text-tx">{lic?.label ?? p.license}</strong>{lic ? ` — ${lic.blurb.toLowerCase()}` : ""}</p>
          <div className="mt-3 flex flex-col gap-2">
            <a href={dl("source")} className="flex items-center justify-center gap-1.5 rounded-[11px] border border-rim-hi bg-well px-3 py-2 text-[12.5px] font-semibold text-tx transition hover:border-violet/50" rel="nofollow"><Icon name="download2" size={12} tone="inherit" /> Source (.zip)</a>
            <a href={dl("jar")} className="flex items-center justify-center gap-1.5 rounded-[11px] border border-rim-hi bg-well px-3 py-2 text-[12.5px] font-semibold text-tx transition hover:border-violet/50" rel="nofollow"><Icon name="download" size={12} tone="inherit" /> Plugin (.jar){cur?.jarSize ? <span className="text-tx-faint">· {Math.max(1, Math.round(cur.jarSize / 1024))} KB</span> : null}</a>
          </div>
          {d.files.length > 0 && <p className="mt-2 text-[11px] text-tx-faint">{d.files.length} source file{d.files.length === 1 ? "" : "s"} · LICENSE included</p>}
        </section>
        {cur?.jarSha256 && (
          <section className="rounded-[16px] border border-rim-hi bg-surface p-4">
            <h2 className="text-[13px] font-extrabold text-tx">Checksum</h2>
            <p className="mt-1 break-all font-mono text-[10.5px] text-tx-faint">sha256 {cur.jarSha256}</p>
          </section>
        )}
      </aside>
    </div>
  );

  const versions = (
    <section className="rounded-[16px] border border-rim-hi bg-surface p-5" aria-label="Versions">
      <h2 className="text-[15px] font-extrabold text-tx">Versions &amp; changelog</h2>
      <ol className="mt-3 flex flex-col">
        {d.versions.map((v, i) => (
          <li key={v.buildId} className="relative flex gap-3 pb-5 last:pb-0">
            <span className="relative flex w-3 flex-none justify-center" aria-hidden>
              <span className={"mt-1.5 h-2.5 w-2.5 rounded-full border-2 " + (v.buildId === d.currentBuildId ? "border-violet bg-violet" : "border-rim-hi bg-surface")} />
              {i < d.versions.length - 1 && <span className="absolute top-5 bottom-[-4px] w-px bg-[var(--color-rim-hi)]" />}
            </span>
            <div className="min-w-0 flex-1">
              <div className="flex flex-wrap items-center gap-2">
                <span className="num text-[14px] font-extrabold text-tx">{versionLabel(v)}</span>
                {v.buildId === d.currentBuildId && <span className="rounded-full border border-violet/40 bg-violet/10 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-violet">Current</span>}
                <span className="text-[11.5px] text-tx-faint">{new Date(v.at).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" })} · MC {v.mcVersion}</span>
              </div>
              <p className="mt-1 whitespace-pre-line text-[13px] leading-relaxed text-tx-body">{v.notes}</p>
              <div className="mt-2 flex flex-wrap gap-3 text-[12px]">
                <a href={dl("jar", v.buildId)} className="font-semibold text-violet hover:underline" rel="nofollow">.jar</a>
                <a href={dl("source", v.buildId)} className="font-semibold text-violet hover:underline" rel="nofollow">source</a>
                {canFork && <ForkButton slug={p.slug} buildId={v.buildId} small label={p.isCreator ? "Open in Cyrus" : "Build on this version"} />}
              </div>
            </div>
          </li>
        ))}
      </ol>
    </section>
  );

  return (
    <div className="flex flex-col gap-5" data-testid="cyrus-mod-page">
      {/* header */}
      <header className="nx-dark-island relative overflow-hidden rounded-[20px] border border-[#7b3fef]/35 bg-[radial-gradient(120%_140%_at_0%_0%,rgba(140,58,233,.35),transparent_55%),linear-gradient(160deg,#071434,#020817)] px-5 py-6 sm:px-7">
        <div className="flex flex-col gap-5 sm:flex-row sm:items-start">
          <span className="grid h-[64px] w-[64px] flex-none place-items-center rounded-[18px] border border-white/15 bg-white/[0.06] text-[#d9ceff]"><CyrusSeal size={36} /></span>
          <div className="min-w-0 flex-1">
            <nav className="text-[11.5px] text-white/55" aria-label="Breadcrumb">
              <Link href={mode === "portal" ? "/dashboard/nxlabs" : "/mods"} className="hover:text-white" prefetch={false}>NxLabs</Link> <span aria-hidden>/</span>{" "}
              <Link href={base} className="hover:text-white" prefetch={false}>Cyrus Mods</Link>
            </nav>
            <div className="mt-1 flex flex-wrap items-center gap-2.5">
              <h1 className="text-[26px] font-extrabold leading-tight tracking-[-0.025em] text-white sm:text-[30px]">{p.title}</h1>
              <CyrusBadge size="sm" tone="onDark" />
              {p.isCreator && <span className={"rounded-full border px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide " + (p.visibility === "PUBLIC" ? "border-emerald-300/40 bg-emerald-300/10 text-emerald-200" : "border-white/25 bg-white/10 text-white/75")}>{p.visibility === "PUBLIC" ? "Public" : "Private — only you"}</span>}
              {p.hidden && <span className="rounded-full border border-red-300/40 bg-red-300/10 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-red-200">Hidden by Nxeon</span>}
            </div>
            {d.tagline && <p className="mt-1.5 max-w-[70ch] text-[14px] leading-relaxed text-white/80">{d.tagline}</p>}
            <p className="mt-2.5 flex flex-wrap gap-x-4 gap-y-1 text-[12px] text-white/60">
              <span>by <strong className="font-semibold text-white/90">{p.creator.name}</strong></span>
              {cur && <span className="num">{versionLabel(cur)}</span>}
              <span>{d.versions.length} version{d.versions.length === 1 ? "" : "s"}</span>
              <span>{p.license}</span>
              <span>updated {new Date(p.updatedAt).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}</span>
              {p.forks > 0 && <span>{p.forks} fork{p.forks === 1 ? "" : "s"}</span>}
              {p.forkOf && <span>forked from <Link href={`${base}/${p.forkOf.slug}`} className="font-semibold text-[#c4b5fd] hover:text-white" prefetch={false}>{p.forkOf.title}</Link></span>}
            </p>
          </div>
          <div className="flex flex-none flex-wrap gap-2 sm:flex-col sm:items-stretch">
            {canFork ? <ForkButton slug={p.slug} label={p.isCreator ? "Open in Cyrus" : "Build on this mod"} /> : (
              <span className="rounded-[11px] border border-white/15 bg-white/[0.05] px-3.5 py-2 text-center text-[12px] text-white/60" title="Cyrus is in private preview">{signedIn ? "Building on mods: soon" : "Sign in to build on it"}</span>
            )}
            <a href={dl("source")} className="rounded-[11px] border border-white/20 bg-white/[0.07] px-3.5 py-2 text-center text-[12.5px] font-semibold text-white transition hover:bg-white/[0.12]" rel="nofollow">Download source</a>
          </div>
        </div>
      </header>

      {(p.isCreator || p.isAdmin) && mode === "portal" && <CyrusOwnerPanel p={p} />}

      <CyrusModTabs
        tabs={[
          { key: "overview", label: "Overview", node: overview },
          { key: "versions", label: `Versions · ${d.versions.length}`, node: versions },
          { key: "community", label: `Community${p.threads.total ? ` · ${p.threads.total}` : ""}`, node: <CyrusCommunity slug={p.slug} signedIn={signedIn} mode={mode} /> },
        ]}
      />
    </div>
  );
