        {p.byCreator && <span className="rounded-[5px] border border-violet/40 bg-violet/10 px-1 text-[9.5px] font-bold uppercase tracking-wide text-violet">Creator</span>}
        <span>· {new Date(p.createdAt).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}</span>
