          {p.reportedByMe && <span className="px-2 py-1 text-[11px]">Reported</span>}
          {p.can.delete && <button type="button" disabled={busy} onClick={() => { if (window.confirm("Delete this post? Replies go with it.")) void act(() => deleteCyrusPost(p.id)); }} className={btn + " hover:text-rose"}>Delete</button>}
        </span>
      </div>
      {reporting && (
        <div className="mt-2 flex flex-wrap items-center gap-2">
          <input value={reason} onChange={(e) => setReason(e.target.value)} maxLength={LIMITS.reasonMax} placeholder="What's wrong with it?" className="input h-8 min-w-[200px] flex-1 text-[12px]" aria-label="Report reason" />
          <button type="button" disabled={busy} onClick={() => act(() => reportCyrusPost(p.id, reason), "Thanks — reported.").then(() => setReporting(false))} className="rounded-[9px] border border-rim-hi bg-surface px-2.5 py-1 text-[12px] font-semibold text-tx">Send report</button>
        </div>
      )}
      {msg && <p className="mt-1 text-[11.5px] text-tx-dim" role="status">{msg}</p>}
    </div>
  );
