"use client";

import { useCallback, useEffect, useState } from "react";
import { Icon } from "@/components/nx/Icon";
import {
  createCyrusPost, deleteCyrusPost, getCommunity, hideCyrusPost, reportCyrusPost, setCyrusPostStatus,
  type CommunityView, type PostView,
} from "@/lib/actions-cyrus-mods";
import { KIND_LABEL, LIMITS, type PostKind } from "@/lib/cyrus-mods/community";

/**
 * Community on a Cyrus mod page: notes, bug reports and fixes (threads), each
 * linked to a version, open/resolved, with comments. Report / hide / delete
 * follow lib/cyrus-mods/community.ts; every action is re-checked on the server.
 */
const KIND_STYLE: Record<PostKind, { cls: string; icon: string }> = {
  NOTE: { cls: "border-cyan/40 bg-cyan/10 text-cyan", icon: "chat" },
  BUG: { cls: "border-rose/40 bg-rose/10 text-rose", icon: "bug" },
  FIX: { cls: "border-mint/40 bg-mint/10 text-mint", icon: "check" },
};
const btn = "rounded-[9px] px-2 py-1 text-[11.5px] font-semibold text-tx-faint transition hover:bg-well hover:text-tx disabled:opacity-50";

function KindChip({ k }: { k: PostKind }) {
  const s = KIND_STYLE[k];
  return <span className={"inline-flex items-center gap-1 rounded-[6px] border px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide " + s.cls}><Icon name={s.icon} size={10} tone="inherit" />{KIND_LABEL[k]}</span>;
}

type Filter = "all" | PostKind;

export function CyrusCommunity({ slug, signedIn, mode }: { slug: string; signedIn: boolean; mode: "portal" | "public" }) {
  const [view, setView] = useState<CommunityView | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [filter, setFilter] = useState<Filter>("all");
  const [status, setStatus] = useState<"all" | "OPEN" | "RESOLVED">("all");
  const [composing, setComposing] = useState(false);

  const load = useCallback(async () => {
    const r = await getCommunity(slug).catch(() => ({ error: "Couldn't load the community." }));
    if (r.view) setView(r.view);
    else setErr(r.error ?? "Couldn't load the community.");
  }, [slug]);
  useEffect(() => { void load(); }, [load]);

  if (!view) return <div className="rounded-[16px] border border-rim-hi bg-surface p-6 text-center text-[12.5px] text-tx-dim">{err ?? "Loading community…"}</div>;

  const shown = view.threads.filter((t) => (filter === "all" || t.kind === filter) && (status === "all" || t.status === status));
  const n = (k: Filter) => (k === "all" ? view.threads.length : view.threads.filter((t) => t.kind === k).length);

  return (
    <section className="flex flex-col gap-3" aria-label="Community" data-testid="cyrus-community">
      <div className="flex flex-wrap items-center gap-2">
        <div className="flex flex-wrap gap-1 rounded-[11px] border border-rim-hi bg-surface p-1" role="group" aria-label="Filter by type">
          {(["all", "BUG", "FIX", "NOTE"] as const).map((k) => (
            <button key={k} type="button" onClick={() => setFilter(k)} aria-pressed={filter === k} className={"rounded-[8px] px-2.5 py-1.5 text-[12px] font-semibold " + (filter === k ? "bg-violet/15 text-tx" : "text-tx-dim hover:text-tx")}>
              {k === "all" ? "All" : k === "BUG" ? "Bugs" : k === "FIX" ? "Fixes" : "Notes"} <span className="num text-tx-faint">{n(k)}</span>
            </button>
          ))}
        </div>
        <select value={status} onChange={(e) => setStatus(e.target.value as typeof status)} aria-label="Status" className="input h-9 text-[12px]">
          <option value="all">Open &amp; resolved</option>
          <option value="OPEN">Open</option>
          <option value="RESOLVED">Resolved</option>
        </select>
        <div className="ml-auto">
          {view.canPost ? (
            <button type="button" onClick={() => setComposing((c) => !c)} className="nx-cta px-4 py-1.5 text-[12.5px]">{composing ? "Close" : "New post"}</button>
          ) : (
            <span className="text-[12px] text-tx-faint">{view.signInHint}{!signedIn && mode === "public" && <> <a href={`/login?next=${encodeURIComponent(`/dashboard/nxlabs/cyrus/${slug}#community`)}`} className="font-semibold text-violet hover:underline">Sign in</a></>}</span>
          )}
        </div>
      </div>

      {composing && <Composer slug={slug} versions={view.versions} onDone={() => { setComposing(false); void load(); }} />}

      {shown.length === 0 ? (
        <div className="rounded-[16px] border border-rim-hi bg-surface px-5 py-10 text-center">
          <Icon name="chat" size={22} className="mx-auto" />
          <p className="mt-2 text-[14px] font-bold text-tx">{view.threads.length ? "Nothing matches that filter" : "No posts yet"}</p>
          <p className="mx-auto mt-1 max-w-[46ch] text-[12.5px] text-tx-dim">Share a tip, report a bug against a version, or post a fix. The creator sees every post.</p>
        </div>
      ) : (
        <ul className="flex flex-col gap-2.5">{shown.map((t) => <Thread key={t.id} t={t} slug={slug} canPost={view.canPost} versions={view.versions} onChanged={load} />)}</ul>
      )}
      <p className="text-[11px] leading-relaxed text-tx-faint">Be kind and stay on topic. Posts reported by {LIMITS.autoHideReports} people are hidden until the creator or Nxeon reviews them.</p>
    </section>
  );
}

function Composer({ slug, versions, onDone, parentId }: { slug: string; versions: { buildId: string; label: string }[]; onDone: () => void; parentId?: string }) {
  const [kind, setKind] = useState<PostKind>("NOTE");
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [buildId, setBuildId] = useState(versions[0]?.buildId ?? "");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const submit = async () => {
    setBusy(true);
    setErr(null);
    const r = await createCyrusPost(slug, { kind, title: parentId ? undefined : title, body, buildId: buildId || null, parentId: parentId ?? null }).catch(() => ({ error: "Couldn't reach Nxeon." }));
    setBusy(false);
    if (r.error) setErr(r.error);
    else onDone();
  };
  return (
    <div className={"flex flex-col gap-2.5 rounded-[14px] border border-rim-hi bg-well p-3.5 " + (parentId ? "" : "border-violet/35")} data-testid={parentId ? "cyrus-reply" : "cyrus-composer"}>
      <div className="flex flex-wrap items-center gap-2">
        <div className="flex gap-1 rounded-[10px] border border-rim-hi bg-surface p-1" role="radiogroup" aria-label="Type">
          {(["NOTE", "BUG", "FIX"] as const).map((k) => (
            <button key={k} type="button" role="radio" aria-checked={kind === k} onClick={() => setKind(k)} className={"rounded-[7px] px-2.5 py-1 text-[12px] font-semibold " + (kind === k ? "bg-violet/15 text-tx" : "text-tx-dim hover:text-tx")}>{KIND_LABEL[k]}</button>
          ))}
        </div>
        {versions.length > 0 && (
          <label className="flex items-center gap-1.5 text-[12px] text-tx-dim">Version
            <select value={buildId} onChange={(e) => setBuildId(e.target.value)} className="input h-8 text-[12px]">
              {!parentId && kind !== "BUG" && <option value="">Any version</option>}
              {parentId && <option value="">—</option>}
              {versions.map((v) => <option key={v.buildId} value={v.buildId}>{v.label}</option>)}
            </select>
          </label>
        )}
      </div>
      {!parentId && <input value={title} onChange={(e) => setTitle(e.target.value)} maxLength={LIMITS.titleMax} placeholder={kind === "BUG" ? "What goes wrong, in a few words" : kind === "FIX" ? "What this fixes" : "Title"} className="input h-10 text-[13px]" aria-label="Title" />}
      <textarea value={body} onChange={(e) => setBody(e.target.value)} maxLength={LIMITS.bodyMax} rows={parentId ? 3 : 5}
        placeholder={kind === "BUG" ? "Steps to reproduce, what you expected, what happened. Console lines help." : kind === "FIX" ? "What you changed (or the Cyrus change request that fixed it)." : "Your note"}
        className="input min-h-[80px] py-2 text-[13px] leading-relaxed" aria-label="Message" />
      {err && <p className="text-[12px] text-rose" role="alert">{err}</p>}
      <div className="flex items-center gap-2">
        <button type="button" onClick={submit} disabled={busy} className="nx-cta px-4 py-1.5 text-[12.5px] disabled:opacity-50">{busy ? "Posting…" : parentId ? "Reply" : "Post"}</button>
        <span className="text-[11px] text-tx-faint">{body.length.toLocaleString()} / {LIMITS.bodyMax.toLocaleString()}</span>
      </div>
    </div>
  );
}

function Thread({ t, slug, canPost, versions, onChanged }: { t: PostView; slug: string; canPost: boolean; versions: { buildId: string; label: string }[]; onChanged: () => void }) {
  const [open, setOpen] = useState(t.comments.length > 0 && t.comments.length <= 3);
  const [replying, setReplying] = useState(false);
  return (
    <li className={"rounded-[14px] border bg-surface p-3.5 " + (t.hidden ? "border-amber/35" : "border-rim-hi")} data-testid="cyrus-thread">
      <div className="flex flex-wrap items-center gap-1.5">
        <KindChip k={t.kind} />
        <span className={"rounded-[6px] border px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide " + (t.status === "RESOLVED" ? "border-mint/40 bg-mint/10 text-mint" : "border-rim-hi bg-well text-tx-dim")}>{t.status === "RESOLVED" ? "Resolved" : "Open"}</span>
        {t.version && <span className="num rounded-[6px] border border-rim-hi bg-well px-1.5 py-0.5 text-[10.5px] text-tx-dim">{t.version}</span>}
        {t.hidden && <span className="rounded-[6px] border border-amber/40 bg-amber/10 px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide text-amber">Hidden</span>}
        {t.reportCount ? <span className="text-[11px] text-amber">{t.reportCount} report{t.reportCount === 1 ? "" : "s"}</span> : null}
      </div>
      <p className="mt-1.5 text-[14px] font-bold text-tx">{t.title}</p>
      <PostBody p={t} />
      <PostMeta p={t} onChanged={onChanged} />
      <div className="mt-2 flex flex-wrap items-center gap-1">
        {t.comments.length > 0 && <button type="button" onClick={() => setOpen((o) => !o)} className={btn}>{open ? "Hide" : "Show"} {t.comments.length} repl{t.comments.length === 1 ? "y" : "ies"}</button>}
        {canPost && !t.hidden && <button type="button" onClick={() => { setReplying((r) => !r); setOpen(true); }} className={btn}>Reply</button>}
      </div>
      {open && t.comments.length > 0 && (
        <ul className="mt-2 flex flex-col gap-2 border-l-2 border-rim-hi pl-3">
          {t.comments.map((c) => (
            <li key={c.id} className={"rounded-[11px] border bg-well px-3 py-2.5 " + (c.hidden ? "border-amber/35" : "border-rim-hi")}>
              <div className="flex flex-wrap items-center gap-1.5">{c.kind !== "NOTE" && <KindChip k={c.kind} />}{c.version && <span className="num text-[10.5px] text-tx-faint">{c.version}</span>}{c.hidden && <span className="text-[10.5px] font-bold uppercase text-amber">Hidden</span>}</div>
              <PostBody p={c} />
              <PostMeta p={c} onChanged={onChanged} />
            </li>
          ))}
        </ul>
      )}
      {replying && <div className="mt-2"><Composer slug={slug} versions={versions} parentId={t.id} onDone={() => { setReplying(false); onChanged(); }} /></div>}
    </li>
  );
}

function PostBody({ p }: { p: PostView }) {
  if (p.hidden && !p.body) return <p className="mt-1 text-[12.5px] italic text-tx-faint">{p.hiddenReason ?? "Hidden"}</p>;
  return (
    <>
      <p className="mt-1 whitespace-pre-line break-words text-[13px] leading-relaxed text-tx-body">{p.body}</p>
      {p.hidden && p.hiddenReason && <p className="mt-1 text-[11.5px] text-amber">{p.hiddenReason}</p>}
    </>
  );
}

function PostMeta({ p, onChanged }: { p: PostView; onChanged: () => void }) {
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [reporting, setReporting] = useState(false);
  const [reason, setReason] = useState("");
  const act = async (fn: () => Promise<{ error?: string }>, after?: string) => {
    setBusy(true);
    setMsg(null);
    const r = await fn().catch(() => ({ error: "Couldn't reach Nxeon." }));
    setBusy(false);
    if (r.error) setMsg(r.error);
    else { if (after) setMsg(after); onChanged(); }
  };
  return (
    <div className="mt-1.5">
      <div className="flex flex-wrap items-center gap-x-1 gap-y-1 text-[11.5px] text-tx-faint">
        <span className="font-semibold text-tx-dim">{p.author}</span>
        {p.byCreator && <span className="rounded-[5px] border border-violet/40 bg-violet/10 px-1 text-[9.5px] font-bold uppercase tracking-wide text-violet">Creator</span>}
        <span>· {new Date(p.createdAt).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}</span>
        <span className="ml-auto flex flex-wrap gap-0.5">
          {p.can.resolve && <button type="button" disabled={busy} onClick={() => act(() => setCyrusPostStatus(p.id, p.status === "OPEN" ? "RESOLVED" : "OPEN"))} className={btn}>{p.status === "OPEN" ? "Mark resolved" : "Reopen"}</button>}
          {p.can.hide && <button type="button" disabled={busy} onClick={() => act(() => hideCyrusPost(p.id, !p.hidden))} className={btn}>{p.hidden ? "Unhide" : "Hide"}</button>}
          {p.can.report && !p.reportedByMe && <button type="button" disabled={busy} onClick={() => setReporting((r) => !r)} className={btn}>Report</button>}
          {p.reportedByMe && <span className="px-2 py-1 text-[11px]">Reported</span>}
          {p.can.delete && <button type="button" disabled={busy} onClick={() => { if (window.confirm("Delete this post? Replies go with it.")) void act(() => deleteCyrusPost(p.id)); }} className={btn + " hover:text-rose"}>Delete</button>}
        </span>
      </div>
      {reporting && (
        <div className="mt-2 flex flex-wrap items-center gap-2">
          <input value={reason} onChange={(e) => setReason(e.target.value)} maxLength={LIMITS.reasonMax} placeholder="What's wrong with it?" className="input h-8 min-w-[200px] flex-1 text-[12px]" aria-label="Report reason" />
          <button type="button" disabled={busy} onClick={() => act(() => reportCyrusPost(p.id, reason), "Thanks — reported.").then(() => setReporting(false))} className="rounded-[9px] border border-rim-hi bg-surface px-2.5 py-1 text-[12px] font-semibold text-tx">Send report</button>
        </div>
      )}
      {msg && <p className="mt-1 text-[11.5px] text-tx-dim" role="status">{msg}</p>}
    </div>
  );
}

