import Link from "next/link";
import { CyrusBadge, CyrusSeal } from "@/components/nx/CyrusBadge";
import type { PageCard } from "@/lib/cyrus-mods/pages";
import { CyrusModCard } from "./CyrusModCard";

/** NxLabs → "Cyrus Mods": mods made with Cyrus. Public pages, plus the viewer's own (private included). */
export function CyrusIndex({ cards, base, q, viewerId, preview, canBuild }: { cards: PageCard[]; base: string; q: string; viewerId: string | null; preview: boolean; canBuild: boolean }) {
  const mine = cards.filter((c) => c.mine);
  const others = cards.filter((c) => !c.mine);
  return (
    <div className="flex flex-col gap-6" data-testid="cyrus-index">
