        <div className="flex flex-col gap-4 sm:flex-row sm:items-center">
          <span className="grid h-[60px] w-[60px] flex-none place-items-center rounded-[18px] border border-white/15 bg-white/[0.06] text-[#d9ceff]"><CyrusSeal size={34} /></span>
          <div className="min-w-0 flex-1">
            <div className="flex flex-wrap items-center gap-2">
              <h1 className="text-[26px] font-extrabold tracking-[-0.025em] text-white sm:text-[30px]">Cyrus Mods</h1>
              <CyrusBadge size="sm" tone="onDark" />
              {preview && <span className="rounded-full border border-amber-300/40 bg-amber-300/10 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-amber-200">Private preview</span>}
            </div>
            <p className="mt-1.5 max-w-[68ch] text-[13.5px] leading-relaxed text-white/75">Paper plugins made with Cyrus, Nxeon&apos;s AI mod studio. Every one is open source: read how it works, download the code, and build your own version on top.</p>
          </div>
          {canBuild && <Link href="/dashboard/cyrus" className="nx-cta flex-none px-4 py-2 text-[13px]" prefetch={false}>Make one with Cyrus</Link>}
        </div>
        <form method="get" action={base} role="search" className="mt-5 flex max-w-[520px] items-center gap-2 rounded-[12px] border border-white/15 bg-white/[0.06] px-3 py-2">
          <input type="search" name="q" defaultValue={q} maxLength={60} placeholder="Search Cyrus mods" aria-label="Search Cyrus mods" className="min-w-0 flex-1 bg-transparent text-[13px] text-white outline-none placeholder:text-white/45" />
          <button type="submit" className="rounded-[9px] bg-white/10 px-3 py-1 text-[12px] font-semibold text-white">Search</button>
        </form>
      </header>

      {viewerId && mine.length > 0 && (
