export async function getCatalogMod(family: string, slug: string): Promise<ModDetail | null> {
  const decodedFamily = safeDecode(family);
  const decodedSlug = safeDecode(slug);
  let row = await db.gameMod.findUnique({ where: { gameFamily_slug: { gameFamily: decodedFamily, slug: decodedSlug } } });
  if (!row && (decodedFamily !== family || decodedSlug !== slug)) {
    row = await db.gameMod.findUnique({ where: { gameFamily_slug: { gameFamily: family, slug } } });
  }
  if (!row || !row.active) return null;
  const aggs = await ratingAggs([row.id]);
  return toDetail(row, aggs.get(row.id));
}

