const T0 = new Date("2026-10-01T10:00:00Z");
const at = (h: number) => new Date(T0.getTime() + h * 3600_000);
const result = (o: Record<string, unknown> = {}) => ({
  summary: { tagline: "Heal yourself", text: "Adds /heal.", howToUse: ["Run /heal"], limitations: ["Cooldown is per player"], changes: "" },
  commands: [{ usage: "/heal", description: "Heal", permission: "heal.use", whoCanUse: "Everyone" }],
  permissions: [{ node: "heal.use", description: "Use /heal", default: "true" }],
  config: [{ key: "cooldown", description: "Seconds", default: "30" }],
  warnings: [], files: [{ path: "src/main/java/Heal.java", size: 900 }, { path: "build/libs/x.jar", size: 1 }], safety: { verdict: "pass", findings: [] }, events: [], repairs: 0, queuePosition: 0,
  ...o,
});
const b = (id: string, o: Partial<ChainBuild> = {}): ChainBuild => ({
  id, status: "succeeded", prompt: "A heal plugin", changeRequest: null, baseBuildId: null, rootBuildId: "r1", mcVersion: "1.21.11",
  pluginName: "Heal", version: "1.0.0", jarName: `Heal-${o.version ?? "1.0.0"}.jar`, jarSize: 4000, jarSha256: "ab", result: result(), cyrus: null, createdAt: T0, finishedAt: T0, ...o,
});

/* ── generated page ─────────────────────────────────────────────────────── */

test("doc: generated from the chain's succeeded versions, newest first, with notes", () => {
  const chain = [
    b("r1", { cyrus: { title: "Heal & Feed" } }),
    b("v2", { baseBuildId: "r1", version: "1.1.0", changeRequest: "Add /feed", createdAt: at(1), finishedAt: at(1), result: result({ summary: { tagline: "Heal and feed", text: "Adds /heal and /feed.", howToUse: [], limitations: [], changes: "Added /feed." } }) }),
    b("v3", { baseBuildId: "v2", status: "failed", version: null, jarName: null, createdAt: at(2) }),
  ];
  const d = buildModDoc(chain, at(3))!;
  assert.equal(d.name, "Heal & Feed", "creator's title wins over the plugin name");
  assert.deepEqual(d.versions.map((v) => v.buildId), ["v2", "r1"], "failed builds are not versions");
  assert.equal(d.versions[0].notes, "Added /feed.", "builder's own change summary");
  assert.equal(d.versions[1].notes, "First version.");
  assert.equal(d.currentBuildId, "v2");
  assert.equal(d.tagline, "Heal and feed");
  assert.equal(d.commands.length, 1);
  assert.deepEqual(d.files.map((f) => f.path), ["src/main/java/Heal.java"], "build output is not source");
  assert.deepEqual(d.compat.software, ["Paper", "Purpur"]);
  assert.equal(readModDoc(JSON.parse(JSON.stringify(d)))?.name, "Heal & Feed");
  assert.equal(readModDoc({ v: 2 }), null);
  assert.equal(buildModDoc([b("x", { status: "failed", jarName: null })]), null, "no page until something succeeds");
});

test("doc: change request is the fallback note; a restored head is the current version", () => {
  const chain = [b("r1", { cyrus: { headBuildId: "r1" } }), b("v2", { baseBuildId: "r1", version: "1.1.0", changeRequest: "Faster cooldown", createdAt: at(1) })];
  const d = buildModDoc(chain)!;
  assert.equal(d.versions[0].notes, "Faster cooldown");
  assert.equal(currentVersion(chain)?.id, "r1");
  assert.equal(d.currentBuildId, "r1");
  assert.equal(versionLabel({ n: 2, version: "v1.1.0" }), "v2 · 1.1.0");
});

test("doc: slugs, licences, package versions", () => {
  assert.equal(slugifyModName("Heal & Feed!"), "heal-feed");
  assert.equal(slugifyModName("Ünïcødé Spleef"), "unicode-spleef");
  assert.equal(slugifyModName("!!"), "cyrus-mod");
  assert.equal(uniqueSlug("heal", new Set(["heal", "heal-2"])), "heal-3");
  assert.equal(isCyrusLicense(DEFAULT_CYRUS_LICENSE), true);
  assert.equal(isCyrusLicense("WTFPL"), false);
  const mit = licenseText("MIT", 2026, "Nick\nEvil");
  assert.match(mit, /^MIT License/);
  assert.match(mit, /Copyright \(c\) 2026 Nick Evil/);
  assert.match(licenseText("GPL-3.0-only", 2026, "N"), /SPDX-License-Identifier: GPL-3.0-only/);
  const chain = [b("r1"), b("aaaaaa1111", { version: "1.1.0" }), b("bbbbbb2222", { version: "1.1.0" })];
  assert.equal(packageVersionFor(chain[0], chain), "1.0.0");
  assert.equal(packageVersionFor(chain[1], chain), "1.1.0+a1111".replace("a1111", "aa1111"));
  assert.notEqual(packageVersionFor(chain[1], chain), packageVersionFor(chain[2], chain), "branches with the same version string stay distinct");
});

