test("gate: hidden until launch except for preview; private pages only for creator/admin", () => {
  assert.equal(cyrusRouteDecision(false, false), "not-found");
  assert.equal(cyrusRouteDecision(false, true), "render");
  assert.equal(cyrusRouteDecision(true, false), "render");
  const page = { userId: "u1", visibility: "PRIVATE", hiddenAt: null };
  assert.equal(pageVisibleTo(page, { id: "u1" }), true);
  assert.equal(pageVisibleTo(page, { id: "u2" }), false);
  assert.equal(pageVisibleTo(page, null), false);
  assert.equal(pageVisibleTo(page, { id: "a", role: "ADMIN" }), true);
  assert.equal(pageVisibleTo({ ...page, visibility: "PUBLIC" }, null), true);
  assert.equal(pageVisibleTo({ ...page, visibility: "PUBLIC", hiddenAt: new Date() }, { id: "u2" }), false, "admin-hidden");
  assert.deepEqual(cyrusSitemapPaths(false, ["heal"]), [], "never advertised before launch");
  assert.deepEqual(cyrusSitemapPaths(true, ["heal"]), ["/mods/cyrus", "/mods/cyrus/heal"]);
});

test("gate: every Cyrus mods route and action is behind the gate (source check)", () => {
  const root = path.resolve(import.meta.dirname, "..");
  const read = (p: string) => readFileSync(path.join(root, p), "utf8");
  for (const p of ["app/dashboard/nxlabs/cyrus/page.tsx", "app/dashboard/nxlabs/cyrus/[slug]/page.tsx", "app/(marketing)/mods/cyrus/page.tsx", "app/(marketing)/mods/cyrus/[slug]/page.tsx"]) {
    const s = read(p);
    assert.match(s, /requireCyrusAccess\(\)/, `${p} must call requireCyrusAccess()`);
    assert.match(s, /cyrusMetadata\(/, `${p} must use cyrusMetadata (noindex until launch)`);
  }
  assert.match(read("app/api/nxlabs/cyrus/[slug]/download/route.ts"), /cyrusAccessFor\(user\)\)\.allowed/);
  const actions = read("lib/actions-cyrus-mods.ts");
  const exported = [...actions.matchAll(/export async function (\w+)/g)].map((m) => m[1]);
  assert.ok(exported.length >= 9);
  for (const fn of exported) {
    const body = actions.slice(actions.indexOf(`export async function ${fn}`)).split(/\nexport async function /)[0];
    assert.match(body, /await viewer\(\)/, `${fn} must check the gate`);
    assert.match(body, /allowed/, `${fn} must refuse outside the gate`);
  }
  assert.match(read("lib/sitemap-sections.ts"), /cyrusModsPublicEnabled\(\)/);
  assert.match(read("middleware.ts"), /isCyrusModsPath\(pathname\)/);
  assert.match(read("lib/settings.ts"), /cyrus_mods_public_enabled: "false"/);
  assert.match(read("app/dashboard/nxlabs/page.tsx"), /cyrus\.allowed && \(/, "NxLabs section only when the gate passes");
});

