test("community: validation", () => {
  const vs = ["v1", "v2"];
  assert.equal(validatePost({ kind: "NOTE", title: "Hi there", body: "Great mod" }, vs).ok, true);
  assert.equal(validatePost({ kind: "SPAM", title: "Hi there", body: "x".repeat(10) }, vs).ok, false);
  assert.equal(validatePost({ kind: "NOTE", title: "Hi", body: "Great" }, vs).ok, false, "title too short");
  assert.equal(validatePost({ kind: "NOTE", title: "Hello", body: "x".repeat(LIMITS.bodyMax + 1) }, vs).ok, false);
  assert.equal(validatePost({ kind: "BUG", title: "Crash on /heal", body: "It crashes" }, vs).ok, false, "a bug needs a version when there are several");
  assert.equal(validatePost({ kind: "BUG", title: "Crash on /heal", body: "It crashes", buildId: "v9" }, vs).ok, false, "foreign version");
  const ok = validatePost({ kind: "bug", title: "  Crash   on /heal ", body: "It\u0007 crashes", buildId: "v2" }, vs);
  assert.ok(ok.ok && ok.post.kind === "BUG" && ok.post.title === "Crash on /heal" && ok.post.body === "It crashes");
  const reply = validatePost({ kind: "FIX", body: "Fixed in v2", parentId: "t1" }, vs);
  assert.ok(reply.ok && reply.post.title === null && reply.post.parentId === "t1", "comments need no title");
  assert.equal(cleanReason("  x "), null);
  assert.equal(cleanReason("spam link"), "spam link");
});

test("community: who may resolve, delete, hide, report", () => {
  const page = { userId: "creator" };
  const thread = { userId: "author", parentId: null };
  const comment = { userId: "author", parentId: "t1" };
  const creator = { id: "creator" }, author = { id: "author" }, other = { id: "other" }, admin = { id: "adm", role: "ADMIN" };
  assert.equal(canModerate(creator, page), true);
  assert.equal(canModerate(admin, page), true);
  assert.equal(canModerate(other, page), false);
  assert.equal(canModerate(null, page), false);
  assert.equal(canResolve(author, page, thread), true);
  assert.equal(canResolve(other, page, thread), false);
  assert.equal(canResolve(author, page, comment), false, "only threads have a status");
  assert.equal(canDelete(author, page, comment), true);
  assert.equal(canDelete(other, page, comment), false);
  assert.equal(canDelete(creator, page, comment), true, "owner delete");
  assert.equal(canDelete(admin, page, comment), true, "admin delete");
  assert.equal(canReport(author, thread), false);
  assert.equal(canReport(other, thread), true);
  assert.equal(canReport(null, thread), false);
  assert.equal(hiddenVisibleTo(other, page, thread), false);
  assert.equal(hiddenVisibleTo(author, page, thread), true);
  assert.equal(rateLimited("thread", LIMITS.threadsPerHour - 1), null);
  assert.ok(rateLimited("thread", LIMITS.threadsPerHour));
  assert.ok(rateLimited("comment", LIMITS.commentsPerHour));
  assert.ok(rateLimited("report", LIMITS.reportsPerDay));
});

/* ── the real engine path for Cyrus jars ────────────────────────────────── */

function pluginJar(name: string, version: string): Buffer {
  return writeZip([
    { name: "plugin.yml", data: Buffer.from(`name: ${name}\nversion: ${version}\nmain: com.nxeon.${name}\napi-version: '1.21'\n`) },
    { name: `com/nxeon/${name}.class`, data: Buffer.from(`fake-class-${version}`) },
  ]);
}

test("engine: a Cyrus mod installs, updates, switches off/on, rolls back and uninstalls with state + backups", async () => {
  const dir = mkdtempSync(path.join(tmpdir(), "cyrus-eng-"));
  try {
    const jars: Record<string, { version: string; bytes: Buffer }> = { r1: { version: "1.0.0", bytes: pluginJar("Heal", "1.0.0") }, v2: { version: "1.1.0", bytes: pluginJar("Heal", "1.1.0") } };
    let current = "r1";
    setCyrusJarSource(async ({ rootBuildId, targetBuildId }) => {
      assert.equal(rootBuildId, "r1");
      const id = targetBuildId ?? current;
      const j = jars[id];
      if (!j) return { error: "That version isn't a finished build of this mod." };
      const out: CyrusJar = { build: { id, version: j.version, pluginName: "Heal", jarName: `Heal-${j.version}.jar`, jarSha256: createHash("sha256").update(j.bytes).digest("hex"), mcVersion: "1.21.11" }, name: "Heal", packageVersion: j.version, bytes: j.bytes };
      return out;
    });
    const fs = new LocalGuestFs(dir);
    await seedSandboxGuest(fs, "minecraft", "paper");
    const server: ServerFacts = { id: "s1", family: "minecraft", variant: "paper", pinnedVersion: "1.21.11", config: null };
    const mod: CatalogFacts = { id: "gm-cyrus", gameFamily: "minecraft", slug: "cyrus-r1", name: "Heal", source: CYRUS_SOURCE, sourceId: "r1", url: null, category: "Plugins", appliesToVariant: null, loaders: ["paper", "purpur"], gameVersions: ["1.21.11"], serverSide: "required" };
    const deps = { fs, fetcher: async () => { throw new Error("Cyrus installs must never download"); } };
    const plugins = path.join(dir, "opt/mc/plugins");

    let r = await installOrUpdate(minecraftInstaller, mod, server, deps);
    assert.ok(r.ok, JSON.stringify(r));
    assert.equal(r.ok && r.versionId, "r1");
    assert.deepEqual(readdirSync(plugins), ["Heal-1.0.0.jar"]);
    let st = await loadState(fs, "minecraft");
    assert.equal(st.roots["gm-cyrus"].key, cyrusPackageKey("r1"), "registered in the engine state");
    assert.equal(st.packages[cyrusPackageKey("r1")].versionId, "r1");

    // idempotent re-run
    r = await installOrUpdate(minecraftInstaller, mod, server, deps);
    assert.ok(r.ok && r.changed.length === 0);

    // update to latest (v2): old jar backed up and replaced
    current = "v2";
    r = await installOrUpdate(minecraftInstaller, { ...mod, targetVersionId: "v2" }, server, deps, "update");
    assert.ok(r.ok && r.versionId === "v2", JSON.stringify(r));
    assert.deepEqual(readdirSync(plugins), ["Heal-1.1.0.jar"]);
    const backups = readdirSync(path.join(dir, "root/.nxeon-mods/backups"));
    assert.ok(backups.some((b) => existsSync(path.join(dir, "root/.nxeon-mods/backups", b, "opt/mc/plugins/Heal-1.0.0.jar"))), "previous jar is in a backup");

    // switch off / on (Paper plugins are SAFE to toggle)
    const d = toggleDecision({ family: "minecraft", variant: "paper", mod: { name: "Heal", category: "Plugins", categories: [], loaders: ["paper"] }, engine: true });
    assert.equal(d.allowed, true);
    r = await setDisabled(minecraftInstaller, mod, server, deps, true);
    assert.ok(r.ok, JSON.stringify(r));
    assert.deepEqual(readdirSync(plugins), []);
    r = await setDisabled(minecraftInstaller, mod, server, deps, false);
    assert.ok(r.ok);
    assert.deepEqual(readdirSync(plugins), ["Heal-1.1.0.jar"]);

    // rollback to v1
    r = await installOrUpdate(minecraftInstaller, { ...mod, targetVersionId: "r1" }, server, deps, "update");
    assert.ok(r.ok && r.versionId === "r1");
    assert.deepEqual(readdirSync(plugins), ["Heal-1.0.0.jar"]);
    st = await loadState(fs, "minecraft");
    assert.equal(st.packages[cyrusPackageKey("r1")].version, "1.0.0");

    // a version that isn't in the chain is refused, nothing changes
    r = await installOrUpdate(minecraftInstaller, { ...mod, targetVersionId: "nope" }, server, deps, "update");
    assert.equal(r.ok, false);
    assert.deepEqual(readdirSync(plugins), ["Heal-1.0.0.jar"]);

    // uninstall
    r = await uninstall(minecraftInstaller, mod, server, deps);
    assert.ok(r.ok);
    assert.deepEqual(readdirSync(plugins), []);
    st = await loadState(fs, "minecraft");
    assert.equal(st.roots["gm-cyrus"], undefined);
  } finally {
    setCyrusJarSource(null);
    rmSync(dir, { recursive: true, force: true });
  }
});

test("engine: Cyrus mods are refused on non-Paper servers and on a checksum mismatch", async () => {
  const dir = mkdtempSync(path.join(tmpdir(), "cyrus-eng2-"));
  try {
    const bytes = pluginJar("Heal", "1.0.0");
    setCyrusJarSource(async () => ({ build: { id: "r1", version: "1.0.0", pluginName: "Heal", jarName: "Heal-1.0.0.jar", jarSha256: "0".repeat(64), mcVersion: "1.21.11" }, name: "Heal", packageVersion: "1.0.0", bytes }));
    const mod: CatalogFacts = { id: "gm", gameFamily: "minecraft", slug: "cyrus-r1", name: "Heal", source: CYRUS_SOURCE, sourceId: "r1", url: null, category: "Plugins", appliesToVariant: null, loaders: ["paper"], gameVersions: [], serverSide: "required" };
    const deps = { fs: new LocalGuestFs(dir), fetcher: async () => { throw new Error("no"); } };
    await seedSandboxGuest(deps.fs, "minecraft", "fabric");
    let r = await installOrUpdate(minecraftInstaller, mod, { id: "s", family: "minecraft", variant: "fabric", pinnedVersion: null, config: null }, deps);
    assert.ok(!r.ok && /Paper plugins/.test(r.error));
    await seedSandboxGuest(deps.fs, "minecraft", "paper");
    r = await installOrUpdate(minecraftInstaller, mod, { id: "s", family: "minecraft", variant: "paper", pinnedVersion: null, config: null }, deps);
    assert.ok(!r.ok && /checksum/.test(r.error));
    assert.equal(minecraftInstaller.compat(mod, { id: "s", family: "minecraft", variant: "spigot", pinnedVersion: null, config: null }).verdict, "mismatch");
  } finally {
    setCyrusJarSource(null);
    rmSync(dir, { recursive: true, force: true });
  }
});

