test("mods tab: one panel, four views, update settings inside Updates, Cyrus badge on rows", () => {
  const root = path.resolve(import.meta.dirname, "..");
  const shell = readFileSync(path.join(root, "components/customer/gamepanel/v2/GamePanelShell.tsx"), "utf8");
  assert.doesNotMatch(shell, /<AutoUpdatePanel/, "auto-updates live under Updates, not stacked below");
  const mods = shell.slice(shell.indexOf('tab === "mods"'), shell.indexOf('tab === "backups"'));
  assert.doesNotMatch(mods, /SubTabs/, "no Mods/Plugins sub-tabs");
  const panel = readFileSync(path.join(root, "components/customer/gamepanel/v2/ModsPanel.tsx"), "utf8");
  for (const v of ['"installed"', '"browse"', '"updates"', '"health"']) assert.ok(panel.includes(`k: ${v}`), v);
  assert.match(panel, /<AutoUpdatePanel serverId=\{serverId\}/);
  assert.match(panel, /#mod-updates/, "notification deep links still land on updates");
  const lib = readFileSync(path.join(root, "components/customer/gamepanel/v2/mods/InstalledLibrary.tsx"), "utf8");
  assert.match(lib, /<CyrusBadge/);
  assert.match(lib, /onVersions/);
});

