// THROWAWAY seed for nxeon_agt_cyrusmods (Mods tab + Cyrus mods verification). Never run against prod.
// Build rows mirror REAL builds served read-only by the local mock of the build service
// (.cyrusmods-local/mocksvc.js, fixtures copied from the Cyrus agent's real-service fetch), and are
// pulled in through the portal's own syncBuild — which stores the real jars and (new) generates pages.
import { createHash } from "node:crypto";
import { writeFileSync } from "node:fs";
import { SignJWT } from "jose";
import { db } from "../lib/db";
import { syncBuild } from "../lib/modbuilder/store";

const MOCK = "http://127.0.0.1:7398";
async function session(userId: string) {
  const token = await new SignJWT({ sub: userId, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("2d").sign(new TextEncoder().encode(process.env.AUTH_SECRET!));
  await db.userSession.create({ data: { userId, tokenHash: createHash("sha256").update(token).digest("hex") } });
  return token;
}

async function main() {
  if (!/nxeon_agt_cyrusmods/.test(process.env.DATABASE_URL ?? "")) throw new Error("refusing: not the throwaway DB");
  const mkUser = async (email: string, name: string, role = "USER") => {
    await db.user.deleteMany({ where: { email } });
    return db.user.create({ data: { email, passwordHash: "x", name, role, emailVerifiedAt: new Date(), heardAboutUs: "other", balanceCents: 2500 } as never });
  };
  await db.cyrusModReport.deleteMany({}); await db.cyrusModPost.deleteMany({}); await db.cyrusFork.deleteMany({}); await db.cyrusModPage.deleteMany({});
  await db.serverMod.deleteMany({}); await db.job.deleteMany({}); await db.modUpdateRun.deleteMany({});
  await db.modBuild.deleteMany({});
  await db.server.deleteMany({ where: { hostname: { startsWith: "agt-cm-" } } });
  await db.gameMod.deleteMany({ where: { gameFamily: "minecraft" } });
  const owner = await mkUser("nicholas.sj.albanese@gmail.com", "Nicholas Albanese");
  const other = await mkUser("sam@example.test", "Sam Builder");
  const outsider = await mkUser("outsider@example.test", "Out Sider");
  const admin = await mkUser("admin@example.test", "Nxeon Staff", "ADMIN");

  const plan = await db.plan.upsert({ where: { slug: "agt-base" }, update: {}, create: { slug: "agt-base", name: "Base", cpuCores: 2, ramMB: 4096, diskGB: 30, priceCents: 500 } });
  const tpl = await db.osTemplate.upsert({ where: { slug: "agt-minecraft" }, update: {}, create: { slug: "agt-minecraft", name: "Minecraft", category: "APPLICATION", family: "minecraft", vmid: 9000, setupScript: "docker run -d --name mc itzg/minecraft-server" } as never });
  const gp = await db.gamePlan.upsert({ where: { id: "agt-gp4" }, update: {}, create: { id: "agt-gp4", name: "Minecraft 4 GB", gameFamily: "minecraft", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 20, priceCents: 1294, basePlanId: plan.id } as never });
  const mk = (userId: string, hostname: string, label: string, variant: string, ip: string) =>
    db.server.create({ data: { name: hostname, label, hostname, userId, planId: plan.id, osTemplateId: tpl.id, gamePlanId: gp.id, status: "RUNNING", gameVariant: variant, gameConfig: { VERSION: "1.21.11" }, ipAddress: ip } as never });
  const smp = await mk(owner.id, "agt-cm-smp", "Survival SMP", "paper", "10.99.2.5");
  const empty = await mk(owner.id, "agt-cm-new", "New world", "paper", "10.99.2.6");
  const otherSrv = await mk(other.id, "agt-cm-sam", "Sam's server", "purpur", "10.99.2.7");

  // Catalogue plugins (the "before" clutter + engine rows).
  const mod = (slug: string, name: string, categories: string[], fileBytes: number, source = "modrinth") =>
    db.gameMod.create({ data: { gameFamily: "minecraft", slug, name, category: "Plugins", categories, loaders: ["paper"], gameVersions: ["1.21.11"], source, sourceId: slug, fileBytes, downloads: 1_000_000, description: `${name} for testing`, serverSide: "required" } as never });
  const lp = await mod("luckperms", "LuckPerms", ["management"], 1_500_000);
  const vault = await mod("vault", "Vault", ["library"], 120_000, "spigotmc");
  const ess = await mod("essentialsx", "EssentialsX", ["utility"], 1_100_000, "spigotmc");
  const we = await mod("worldedit", "WorldEdit", ["utility"], 3_400_000);
  for (let i = 0; i < 8; i++) await mod(`extra-${i}`, `Catalogue Plugin ${i + 1}`, ["utility"], 200_000 + i * 1000);
  const sm = (serverId: string, modId: string, status: string, version: string, extra: Record<string, unknown> = {}) => db.serverMod.create({ data: { serverId, modId, status, version, ...extra } });
  await sm(smp.id, lp.id, "INSTALLED", "5.4.141", { availableVersion: "5.4.150" });
  await sm(smp.id, vault.id, "INSTALLED", "1.7.3");
  await sm(smp.id, ess.id, "INSTALLED", "2.20.1");
  await sm(smp.id, we.id, "DISABLED", "7.3.6");
  await db.job.create({ data: { type: "GAME_MOD_SYNC", serverId: smp.id, status: "DONE", progress: 100, payload: { op: "disable", modId: we.id, result: { restartRequired: false, changed: [], failed: [], deps: { [lp.id]: [], [vault.id]: [], [ess.id]: [vault.id], [we.id]: [] } } } } as never });
  await db.modUpdateRun.create({ data: { serverId: smp.id, trigger: "health", status: "HEALTH_WARN", summary: "EssentialsX logged an error while enabling.", plan: { startedAt: new Date().toISOString(), verdicts: [{ name: "LuckPerms", status: "loaded", evidence: "[LuckPerms] Enabling LuckPerms v5.4.141" }, { name: "Vault", status: "loaded", evidence: "[Vault] Enabling Vault v1.7.3" }, { name: "EssentialsX", status: "error", evidence: "Error occurred while enabling EssentialsX v2.20.1" }] }, finishedAt: new Date() } as never });

  // Cyrus builds (owner): Heal v1 -> v2, DailyRewards v1 -> v2, Spleef v1. Other user: SimpleEconomy (to publish).
  const fx = async (id: string) => (await fetch(`${MOCK}/builds/${id}`).then((r) => r.json())) as { prompt: string; mcVersion: string; changeRequest?: string; baseBuildId?: string };
  const min = (m: number) => new Date(Date.now() - m * 60_000);
  const row = async (userId: string, id: string, createdAt: Date, extra: Record<string, unknown> = {}) => {
    const f = await fx(id);
    return db.modBuild.create({ data: { id, userId, prompt: f.prompt, mcVersion: f.mcVersion, rootBuildId: (extra.rootBuildId as string) ?? id, changeRequest: f.changeRequest ?? null, createdAt, ...extra } as never });
  };
  await row(owner.id, "p0-heal01", min(600), { cyrus: { title: "Heal & Feed", model: "katara" } });
  await row(owner.id, "p0-heal01c1", min(500), { baseBuildId: "p0-heal01", rootBuildId: "p0-heal01" });
  await row(owner.id, "mb67f7a97b866da50800f4", min(400));
  await row(owner.id, "mb16f8378db9c3e2b68cbe", min(300), { baseBuildId: "mb67f7a97b866da50800f4", rootBuildId: "mb67f7a97b866da50800f4" });
  await row(owner.id, "p0-spleef01", min(200));
  await row(other.id, "p0-econ01", min(100));
  // The real portal sync: status + result from the service, the jar downloaded + checksummed, page generated.
  for (const b of await db.modBuild.findMany({ orderBy: { createdAt: "asc" } })) await syncBuild(b);

  const out = {
    owner: { id: owner.id, token: await session(owner.id) },
    other: { id: other.id, token: await session(other.id) },
    outsider: { id: outsider.id, token: await session(outsider.id) },
    admin: { id: admin.id, token: await session(admin.id) },
    smp: smp.id, empty: empty.id, otherSrv: otherSrv.id,
    cookie: process.env.NXEON_COOKIE_NAME ?? "nxeon_session",
    pages: await db.cyrusModPage.findMany({ select: { slug: true, rootBuildId: true, userId: true, visibility: true } }),
    builds: await db.modBuild.findMany({ select: { id: true, status: true, version: true, jarName: true, jarSha256: true } }),
  };
  writeFileSync(new URL("./seed-out.json", import.meta.url), JSON.stringify(out, null, 2));
  console.log(JSON.stringify({ pages: out.pages, builds: out.builds }, null, 1));
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });

