cd /tank/nxeon-wt-cyrusmods/.cyrusmods-local; cat > miniworker.ts <<'EOF'
// THROWAWAY mini worker for nxeon_agt_cyrusmods: runs the REAL worker handler for GAME_MOD_SYNC
// (worker/game-mods.ts gameModSync → lib/mods/engine.ts against the SANDBOX fake guest dir).
// GAME_POWER / GAME_BACKUP are only marked DONE (simulated — there is no game process here).
import { db } from "../lib/db";
import { gameModSync } from "../worker/game-mods";
if (!/nxeon_agt_cyrusmods/.test(process.env.DATABASE_URL ?? "") || process.env.NXEON_SANDBOX !== "1") throw new Error("refusing: throwaway sandbox only");
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
for (;;) {
  const job = await db.job.findFirst({ where: { status: "QUEUED", type: { in: ["GAME_MOD_SYNC", "GAME_POWER", "GAME_BACKUP"] } }, orderBy: { createdAt: "asc" } });
  if (!job) { await sleep(1000); continue; }
  const claimed = await db.job.updateMany({ where: { id: job.id, status: "QUEUED" }, data: { status: "RUNNING" } });
  if (!claimed.count) continue;
  try {
    if (job.type === "GAME_MOD_SYNC") await gameModSync(job);
    else await sleep(1500);
    await db.job.update({ where: { id: job.id }, data: { status: "DONE", error: null, finishedAt: new Date() } });
    console.log(new Date().toISOString(), "DONE", job.type, job.id, JSON.stringify(job.payload));
  } catch (e) {
    await db.job.update({ where: { id: job.id }, data: { status: "FAILED", error: String((e as Error).message).slice(0, 500), finishedAt: new Date() } });
    console.log(new Date().toISOString(), "FAILED", job.type, job.id, (e as Error).message);
  }
}
EOF
cd ..; set -a; . ./.env; set +a; nohup nice -n 15 npx tsx .cyrusmods-local/miniworker.ts > .cyrusmods-local/worker.log 2>&1 & echo $! > .cyrusmods-local/worker.pid; sleep 6; cat .cyrusmods-local/worker.log

