import { notFound } from "next/navigation";
import { revalidatePath } from "next/cache";
import type { Metadata } from "next";
import { db } from "@/lib/db";
import { requireAdmin, realUser } from "@/lib/auth";
import { isPreviewUser } from "@/lib/preview-access";
import { setSetting } from "@/lib/settings";
import { CYRUS_MODS_PUBLIC_FLAG, cyrusModsPublicEnabled } from "@/lib/cyrus-mods/gate";
import { PageHeader, Badge, StatCard, timeAgo } from "@/components/ui/primitives";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  const ok = await isPreviewUser(await realUser().catch(() => null), "modbuilder");
  return { title: ok ? "Cyrus mods" : "Page not found", robots: { index: false, follow: false } };
}

async function setLaunch(form: FormData) {
  "use server";
  const admin = await requireAdmin();
  const on = form.get("on") === "1";
  await setSetting(CYRUS_MODS_PUBLIC_FLAG, on ? "true" : "false");
  await db.auditLog.create({ data: { userId: admin.id, action: "cyrusmods.launch", detail: on ? "on" : "off" } }).catch(() => {});
  revalidatePath("/admin/cyrus-mods");
}

async function resolveReports(form: FormData) {
  "use server";
  const admin = await requireAdmin();
  const postId = String(form.get("postId") ?? "");
  const hide = form.get("hide") === "1";
  const post = await db.cyrusModPost.findUnique({ where: { id: postId } });
  if (!post) return;
  await db.cyrusModReport.updateMany({ where: { postId, resolvedAt: null }, data: { resolvedAt: new Date() } });
  await db.cyrusModPost.update({ where: { id: postId }, data: hide ? { hiddenAt: post.hiddenAt ?? new Date(), hiddenById: admin.id, hiddenReason: "Hidden by Nxeon after review" } : { hiddenAt: null, hiddenById: null, hiddenReason: null, reportCount: 0 } });
  await db.auditLog.create({ data: { userId: admin.id, action: hide ? "cyrusmods.report.hide" : "cyrusmods.report.dismiss", detail: postId } }).catch(() => {});
  revalidatePath("/admin/cyrus-mods");
}

/**
 * Cyrus mods (NxLabs pages + community). URL-only while Cyrus is in private
 * preview: gated on ADMIN and the modbuilder preview allowlist. Holds the ONE
 * launch switch (Setting cyrus_mods_public_enabled) and the report queue.
 */
export default async function AdminCyrusModsPage() {
  await requireAdmin();
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  const [on, pages, reports, posts] = await Promise.all([
    cyrusModsPublicEnabled(),
    db.cyrusModPage.findMany({ orderBy: { updatedAt: "desc" }, take: 200 }),
    db.cyrusModReport.findMany({ where: { resolvedAt: null }, orderBy: { createdAt: "desc" }, take: 200 }),
    db.cyrusModPost.count(),
  ]);
  const reported = await db.cyrusModPost.findMany({ where: { id: { in: [...new Set(reports.map((r) => r.postId))] } } });
  const users = await db.user.findMany({ where: { id: { in: [...new Set([...pages.map((p) => p.userId), ...reported.map((p) => p.userId)])] } }, select: { id: true, email: true } });
  const email = new Map(users.map((u) => [u.id, u.email]));
  const pageOf = new Map(pages.map((p) => [p.id, p]));
  return (
    <div>
      <PageHeader title="Cyrus mods" sub="Auto-generated NxLabs pages for mods built with Cyrus, their community threads, and the public launch switch.">
        {on ? <Badge tone="green">public: launched</Badge> : <Badge tone="brand">preview only</Badge>}
      </PageHeader>
      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Mod pages" value={String(pages.length)} delta={`${pages.filter((p) => p.visibility === "PUBLIC").length} published`} />
        <StatCard label="Community posts" value={String(posts)} />
        <StatCard label="Open reports" value={String(reports.length)} />
        <StatCard label="Hidden pages" value={String(pages.filter((p) => p.hiddenAt).length)} />
      </div>
      <div className="card mb-6">
        <p className="text-sm font-semibold">Public launch</p>
        <p className="mt-1 text-xs text-slate-400">Off: /mods/cyrus/**, /dashboard/nxlabs/cyrus/**, downloads, community and fork 404 for everyone except preview accounts; noindex; not in the sitemap. On: everyone can see PUBLISHED pages (pages stay private until their creator publishes). Building on a mod still needs Cyrus access.</p>
        <form action={setLaunch} className="mt-3">
          <input type="hidden" name="on" value={on ? "0" : "1"} />
          <button type="submit" className={on ? "btn-secondary" : "btn-primary"}>{on ? "Turn public launch off" : "Launch Cyrus mods publicly"}</button>
        </form>
      </div>
      <div className="card mb-6 overflow-x-auto">
        <p className="mb-2 text-sm font-semibold">Reported posts</p>
