http.createServer(async (req, res) => {
  const url = new URL(req.url, "http://x");
  const parts = url.pathname.split("/").filter(Boolean);
  if (url.pathname === "/health") return send(res, 200, { ok: true, service: "mock", image: "0.4-mock", features: { images: true, live: true } });
  if (req.method === "POST" && url.pathname === "/_set") {
    const b = await readBody(req);
    const fxId = b.fx || fixtureFor(b.prompt || "", b.changeRequest);
    if (b.status === "succeeded") { recs.set(b.id, { id: b.id, fx: fxId, static: { ...fixtures[fxId], id: b.id, prompt: b.prompt, changeRequest: b.changeRequest || null, baseBuildId: b.baseBuildId || null, mcVersion: b.mcVersion, durationMs: 90000, finishedAt: now() } }); return send(res, 200, { ok: true }); }
    if (b.status === "failed") { recs.set(b.id, { id: b.id, fx: fxId, static: { ...fixtures[b.fx], id: b.id } }); return send(res, 200, { ok: true }); }
    const tl = timeline(fxId);
    const e = { id: b.id, body: b, fxId, fx: fxId, tl, t0: Date.now() - (b.ago || 30) * 1000, references: b.references || [] };
    const at = { queued: 0.5, planning: 2.5, coding: 4 + (tl.codingEnd - 4) * (b.livePct ?? 0.55), compiling: tl.codingEnd + 1, repairing: tl.codingEnd + 1, scanning: tl.compileEnd + 1 }[b.status];
    if (at !== undefined && !b.run) { e.frozen = at; e.t0 = Date.now() - at * 1000; }
    else if (at !== undefined) e.t0 = Date.now() - at * 1000;
    recs.set(b.id, e);
    return send(res, 200, { ok: true, status: stageAt(tl, at ?? 0), fx: fxId });
  }
  if (req.method === "POST" && url.pathname === "/builds") {
    const b = await readBody(req);
    if (b.tier !== undefined && !["katara", "saka", "yakko"].includes(b.tier)) return send(res, 400, { error: "bad tier" });
    const fxId = fixtureFor(b.prompt, b.changeRequest);
    const references = (b.images || []).map((im, i) => ({ n: i + 1, name: im.name, type: im.type, size: Buffer.from(im.data || "", "base64").length }));
    const e = { id: b.id, body: b, fxId, fx: fxId, tl: timeline(fxId), t0: Date.now(), references };
    recs.set(b.id, e);
    console.log("create", b.id, fxId, JSON.stringify({ tier: b.tier, images: references.length, keys: Object.keys(b) }));
    return send(res, 202, recOf(e));
  }
  if (parts[0] === "builds" && parts[1]) {
    const e = get(parts[1]);
    if (!e) return send(res, 404, { error: "not found" });
    const rec = recOf(e);
    if (req.method === "GET" && parts.length === 2) return send(res, 200, rec);
    if (req.method === "POST" && parts[2] === "cancel") { e.static = { ...rec, status: "failed", errorCode: "cancelled", error: "Build cancelled.", finishedAt: now() }; return send(res, 200, { ok: true }); }
    if (parts[2] === "live") return send(res, 200, e.static ? { live: false, status: rec.status, files: [], draft: null } : liveView(e, url.searchParams));
    if (parts[2] === "artifact") {
      const f = path.join(FX, `${e.fx}.jar.bin`);
      if (!fs.existsSync(f)) return send(res, 404, {});
      return res.end(fs.readFileSync(f));
    }
    if (parts[2] === "source") {
      const p = String(url.searchParams.get("path") || "");
      if (rec.status !== "succeeded" && rec.status !== "failed") {
        const lv = liveView(e, new URLSearchParams());
        if (!lv.files.some((f) => f.path === p)) return send(res, 404, { error: "no such file" });
      }
      const f = path.join(FX, "src", e.fx, p);
      if (!f.startsWith(path.join(FX, "src", e.fx)) || !fs.existsSync(f)) return send(res, 404, { error: "no such file" });
      res.writeHead(200, { "Content-Type": "text/plain; charset=utf-8" });
      return res.end(fs.readFileSync(f));
    }
  }
  send(res, 404, { error: "nope" });
}).listen(PORT, "127.0.0.1", () => console.log("mock modbuilder (0.4 live) on", PORT, Object.keys(fixtures).length, "fixtures"));

