import fs from "node:fs";
import { browser, ctxFor, open, shot, errors, BASE } from "./lib.mjs";
const log = (...a) => console.log(...a);
const D = "/tank/nxeon-cyrusmods-data";
const b = await browser();

// Report (Sam reports the creator's reply)
{
  const sam = await ctxFor(b, "other", "1440", "dark");
  const { p } = await open(sam, "/dashboard/nxlabs/cyrus/heal-feed#community", "sam-report", 3500);
  await p.getByRole("tab", { name: /^Community/ }).click(); await p.waitForTimeout(1500);
  await p.getByRole("button", { name: "Report", exact: true }).first().click();
  await p.getByLabel("Report reason").fill("Testing the report flow");
  await p.getByRole("button", { name: "Send report" }).click();
  await p.waitForTimeout(2500);
  log("sam report msg:", await p.getByText("Thanks — reported.").count(), "reported-badge:", await p.getByText("Reported", { exact: true }).count());
  await sam.close();
}
// Source + jar download (creator)
{
  const own = await ctxFor(b, "owner");
  for (const what of ["source", "jar"]) {
    const res = await own.request.get(`${BASE}/api/nxlabs/cyrus/heal-feed/download?what=${what}`);
    const buf = await res.body();
    log("download", what, res.status(), res.headers()["content-disposition"], buf.length);
    if (what === "source" && res.status() === 200) fs.writeFileSync("/root/agent-notes/cyrus-mods/heal-feed-source.zip", buf);
  }
  await own.close();
}
// Gate bodies BEFORE launch
const gate = async (label) => {
  for (const who of ["outsider", null]) {
    const c = await ctxFor(b, who);
    for (const path of ["/dashboard/nxlabs/cyrus/heal-feed", "/mods/cyrus", "/mods/cyrus/heal-feed", "/mods/cyrus/spleef", "/api/nxlabs/cyrus/heal-feed/download?what=jar"]) {
      const res = await c.request.get(BASE + path, { maxRedirects: 0 });
      const body = await res.text();
      const visible = body.replace(/<script[\s\S]*?<\/script>/g, "").replace(/<[^>]+>/g, " ");
      const title = (/<title>([^<]*)<\/title>/.exec(body) ?? [])[1] ?? "";
      log(label, who ?? "anon", path, res.status(), `title="${title}"`, /noindex/.test(body) ? "noindex" : "INDEXABLE", /Heal & Feed|Heal &amp; Feed/.test(visible) ? "SHOWS-MOD" : "no-mod-content", /This page could not be found|Page not found|404/.test(visible) ? "not-found-ui" : "");
      fs.writeFileSync(`${D}/gate-${label}-${who ?? "anon"}-${path.replace(/[^a-z0-9]+/gi, "_")}.html`, body);
    }
    await c.close();
  }
};
await gate("before");
// Launch via the admin page (real server action), check public, then turn it back off.
{
  const adm = await ctxFor(b, "admin", "1440", "dark");
  let { p } = await open(adm, "/admin/cyrus-mods", "admin", 2500);
  await shot(p, "admin-cyrus-mods-1440-dark");
  await p.getByRole("button", { name: "Launch Cyrus mods publicly" }).click(); await p.waitForTimeout(2500);
  log("launched badge:", await p.getByText("public: launched").count());
  await gate("launched");
  const sm = await (await adm.request.get(`${BASE}/sitemap.xml`)).text();
  const core = /<loc>([^<]*core[^<]*)<\/loc>/.exec(sm)?.[1];
  const coreXml = core ? await (await adm.request.get(core.replace(/^https?:\/\/[^/]+/, BASE))).text() : "";
  log("sitemap core has /mods/cyrus/heal-feed:", coreXml.includes("/mods/cyrus/heal-feed"), "has private spleef:", coreXml.includes("/mods/cyrus/spleef"), "core url:", core);
  const anon = await ctxFor(b, null, "1440", "dark");
  const pub = await open(anon, "/mods/cyrus/heal-feed", "anon-public", 3000);
  await shot(pub.p, "launched-public-page-anon-1440-dark");
  await pub.p.getByRole("tab", { name: /^Community/ }).click(); await pub.p.waitForTimeout(1500);
  await shot(pub.p, "launched-public-community-anon-1440-dark");
  await anon.close();
  ({ p } = await open(adm, "/admin/cyrus-mods", "admin2", 2000));
  await p.getByRole("button", { name: "Turn public launch off" }).click(); await p.waitForTimeout(2500);
  log("launch off badge:", await p.getByText("preview only").count());
  await adm.close();
  await gate("after-off");
}
await b.close();
log("ERRORS", JSON.stringify(errors.slice(0, 20), null, 1));

