import { db } from "../lib/db";
import { sectionEntries } from "../lib/sitemap-sections";
import { setSetting } from "../lib/settings";
async function main() {
  if (!/nxeon_agt_cyrusmods/.test(process.env.DATABASE_URL ?? "")) throw new Error("refusing");
  for (const on of ["false", "true", "false"]) {
    await setSetting("cyrus_mods_public_enabled", on);
    const e = (await sectionEntries("core")).map((x) => x.url).filter((u) => u.includes("/mods/cyrus"));
    console.log("flag", on, "->", JSON.stringify(e));
  }
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });
EOF
set -a; . ./.env; set +a; nice -n 15 npx tsx .cyrusmods-local/sitemap-check.ts 2>&1 | tail -4

