import { db } from "../lib/db";
import { setSetting } from "../lib/settings";
import { getCommunity } from "../lib/actions-cyrus-mods";
async function main() {
  if (!/nxeon_agt_cyrusmods/.test(process.env.DATABASE_URL ?? "")) throw new Error("refusing");
  await setSetting("cyrus_mods_public_enabled", "true");
  const r = await getCommunity("heal-feed");
  console.log("launched anon:", r.error ?? `${r.view?.threads.length} threads, canPost=${r.view?.canPost}, hint=${r.view?.signInHint}`);
  await setSetting("cyrus_mods_public_enabled", "false");
  const r2 = await getCommunity("heal-feed");
  console.log("not launched anon:", r2.error ?? "VISIBLE");
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });
EOF
set -a; . ./.env; set +a; nice -n 15 npx tsx .cyrusmods-local/anon-community.ts 2>&1 | tail -4

